// Junta o andamento da criação, os arquivos e o vídeo. Sem a chave certa, o link de editar e a chave não saem
// (o código da apresentação é público: está no link que o público recebe).
// Os nomes dos nodes vão escritos por extenso, entre aspas: o renomeador de emojis não corrige nome guardado em variável.
const q = $('🔔 Consulta status (GET)').first().json.query || {};
const le = v => { try { return JSON.parse(v || 'null'); } catch (e) { return null; } };
const st = le($('📖 Lê o status').first().json.st), arq = le($('📖 Lê os arquivos (status)').first().json.arq), vid = le($('📖 Lê o vídeo (status)').first().json.vid);
if (!st) return [{ json: { resposta: JSON.stringify({ etapa: 'nao_encontrado' }) } }];
const dono = !!q.chave && q.chave === st.chave;
const r = Object.assign({}, st, { arq, vid, dono });
delete r.chave;
if (!dono) delete r.editar;
return [{ json: { resposta: JSON.stringify(r) } }];

// Regras do conteúdo dos slides (iguais na redatora, na revisora e na edição do dono).
const apT = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const apEmoji = (v, k) => { const m = String(v || '').match(/\p{Extended_Pictographic}(️|‍\p{Extended_Pictographic})*/u); return m ? m[0] : ['💡', '✅', '🎯', '🚀', '📌'][k % 5]; };
// todos os números de um texto ("R$ 48 mil" = 48 e 48000; "1.240" = 1240; "4,5" = 4.5)
function apNumeros(t) {
  const out = [], s0 = String(t || ''), re = /\d[\d.,]*/g;
  let m;
  while ((m = re.exec(s0))) {
    const s = m[0].replace(/[.,]+$/, ''), depois = s0.slice(m.index + m[0].length, m.index + m[0].length + 12).toLowerCase();
    const mult = /^\s*(mil\b|k\b)/.test(depois) ? 1e3 : /^\s*(milh|mi\b)/.test(depois) ? 1e6 : /^\s*(bilh|bi\b)/.test(depois) ? 1e9 : 1;
    for (const v of [Number(s.replace(/\./g, '').replace(',', '.')), Number(s.replace(/,/g, ''))]) {
      if (isFinite(v)) { out.push(v); if (mult > 1) out.push(v * mult); }
    }
  }
  return [...new Set(out)];
}
const apConfere = (v, lista) => lista.some(x => Math.abs(x - v) <= Math.max(0.011, Math.abs(x) * 0.005));
const apNumeroDoGrafico = v => typeof v === 'number' ? v : Number(String(v ?? '').replace(/[^\d,.\-]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.'));
// só os campos do layout, com tamanho máximo e listas na quantidade certa
function apSaneia(s, layout) {
  s = s || {};
  const o = { n: s.n, layout, titulo: apT(s.titulo, 90), notas: apT(s.notas, 600), narracao: apT(s.narracao, 700).replace(/\p{Extended_Pictographic}/gu, '').trim() };
  const itens = (max, lt, ld, ico = true) => (Array.isArray(s.itens) ? s.itens : []).map((it, k) => ({
    icone: ico ? apEmoji(it && it.icone, k) : '', t: apT(it && (typeof it === 'string' ? it : it.t || it.titulo), lt), d: apT(it && (it.d || it.texto || it.descricao), ld) })).filter(it => it.t).slice(0, max);
  if (layout === 'capa') o.subtitulo = apT(s.subtitulo, 140);
  else if (layout === 'secao') o.texto = apT(s.texto, 160);
  else if (layout === 'topicos') { o.itens = itens(5, 48, 130); if (o.itens.length < 2) { o.texto = apT(s.texto || o.itens.map(i => i.t + (i.d ? ': ' + i.d : '')).join(' · ') || s.notas, 400); o.itens = []; } }
  else if (layout === 'imagem_texto') { o.texto = apT(s.texto, 360); o.itens = o.texto ? [] : itens(3, 44, 110); }
  else if (layout === 'colunas') o.itens = itens(4, 36, 150);
  else if (layout === 'etapas') o.itens = itens(5, 32, 110, false);
  else if (layout === 'numeros') o.numeros = (Array.isArray(s.numeros) ? s.numeros : []).map(x => ({ v: apT(x && x.v, 14), r: apT(x && x.r, 40), d: apT(x && x.d, 90) })).filter(x => x.v && x.r).slice(0, 4);
  else if (layout === 'grafico') {
    const g = s.grafico || {}, n = Math.min((g.rotulos || []).length, (g.valores || []).length, 12);
    o.destaque = apT(s.destaque, 140);
    // "R$" + 39 + "mil" vira "R$ 39 mil" (o % fica colado: "23%")
    const pre = apT(g.prefixo, 6), suf = apT(g.sufixo, 10);
    o.grafico = { tipo: ['barras', 'barras_h', 'linha'].includes(g.tipo) ? g.tipo : 'barras', titulo: apT(g.titulo, 60), rotulos: (g.rotulos || []).slice(0, n).map(x => apT(x, 30)),
      valores: (g.valores || []).slice(0, n).map(apNumeroDoGrafico), prefixo: pre ? pre + ' ' : '', sufixo: /^[A-Za-zÀ-ú]/.test(suf) ? ' ' + suf : suf, fonte: apT(g.fonte, 80) };
  } else if (layout === 'comparacao') {
    const c = s.comparacao || {}, lado = x => ({ titulo: apT(x && x.titulo, 26), itens: (Array.isArray(x && x.itens) ? x.itens : []).map(i => apT(typeof i === 'string' ? i : i && (i.t || i.texto), 90)).filter(Boolean).slice(0, 5) });
    o.comparacao = { a: lado(c.a), b: lado(c.b) };
  } else if (layout === 'citacao') { const c = s.citacao || {}; o.citacao = { texto: apT(c.texto || s.texto, 240), autor: apT(c.autor, 70) }; }
  else if (layout === 'fechamento') o.texto = apT(s.texto, 180);
  return apEstrutura(o);
}
// o que não dá para mostrar no layout pedido vira tópicos (lista vazia, gráfico sem números, comparação com um lado só)
function apEstrutura(o) {
  const vira = (itens, texto) => Object.assign({ n: o.n, layout: 'topicos', titulo: o.titulo, notas: o.notas, narracao: o.narracao }, itens.length >= 2 ? { itens } : { itens: [], texto: apT(texto || o.notas, 400) });
  if (o.layout === 'grafico' && !(o.grafico.valores.length >= 2 && o.grafico.valores.every(v => isFinite(v)))) return vira([], o.destaque);
  if (o.layout === 'numeros' && o.numeros.length < 2) return vira(o.numeros.map((x, k) => ({ icone: apEmoji('', k), t: x.v + ' ' + x.r, d: x.d })), '');
  if ((o.layout === 'colunas' || o.layout === 'etapas') && o.itens.length < 2) return vira(o.itens.map((x, k) => ({ icone: apEmoji(x.icone, k), t: x.t, d: x.d })), '');
  if (o.layout === 'comparacao' && !(o.comparacao.a.itens.length && o.comparacao.b.itens.length)) {
    const it = o.comparacao.a.itens.concat(o.comparacao.b.itens).map((t, k) => ({ icone: apEmoji('', k), t, d: '' }));
    return vira(it, '');
  }
  if (o.layout === 'citacao' && !o.citacao.texto) return vira([], o.notas);
  if (o.layout === 'fechamento' && !o.titulo) o.titulo = 'Obrigado!';
  return o;
}
// números do slide que não estão nos dados do usuário (gráfico e "números")
function apNumerosFora(o, lista) {
  if (o.layout === 'grafico') return o.grafico.valores.filter(v => !apConfere(v, lista)).map(v => String(v).replace('.', ','));
  if (o.layout === 'numeros') return o.numeros.filter(x => !apNumeros(x.v).some(v => apConfere(v, lista))).map(x => x.v);
  return [];
}
// tira os números que não vieram do usuário (o slide continua, sem eles)
function apSemNumeros(o, lista) {
  if (o.layout === 'numeros') {
    const bons = o.numeros.filter(x => apNumeros(x.v).some(v => apConfere(v, lista)));
    return apEstrutura(Object.assign({}, o, { numeros: bons }));
  }
  if (o.layout === 'grafico') return apEstrutura(Object.assign({}, o, { grafico: Object.assign({}, o.grafico, { valores: [] }) }));
  return o;
}

// Confere o pedido: assunto, conteúdo, público, objetivo, quantidade de slides, tema visual, cor, imagens e vídeo.
let b = $('🔔 Pedido da apresentação (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const crypto = require('crypto');
const limpa = (v, max) => String(v ?? '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>{}\\]/g, ' ').replace(/[ \t]+/g, ' ').trim().slice(0, max);
const texto = (v, max) => String(v ?? '').replace(/\r/g, '').replace(/[\u0000-\u0008\u000b-\u001f\u007f<>{}\\]/g, ' ').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, max);
const OBJETIVOS = { informar: 'informar / relatório de resultados', vender: 'vender ou convencer', ensinar: 'ensinar (aula ou treinamento)', inspirar: 'inspirar (palestra)', pitch: 'apresentar um projeto (pitch)' };
const TONS = { profissional: 'profissional', descontraido: 'descontraído', didatico: 'didático', inspirador: 'inspirador' };
const TEMAS = ['claro', 'escuro', 'elegante', 'vibrante', 'corporativo'];
const VOZES = ['pt-BR-ThalitaMultilingualNeural', 'pt-BR-FranciscaNeural', 'en-US-AndrewMultilingualNeural', 'en-US-BrianMultilingualNeural'];
const TRILHAS = ['nenhuma', 'calmo', 'chill', 'elegante', 'emocional'];
const dados = {
  tema: texto(b.tema, 1500), conteudo: texto(b.conteudo, 8000), publico: limpa(b.publico, 200), autor: limpa(b.autor, 80),
  contatos: String(b.contatos || '').split('\n').map(c => limpa(c, 80)).filter(Boolean).slice(0, 3),
  objetivo: OBJETIVOS[b.objetivo] ? b.objetivo : 'informar', tom: TONS[b.tom] ? b.tom : 'profissional',
};
const op = {
  slides: Math.min(15, Math.max(6, parseInt(b.slides, 10) || 10)), visual: TEMAS.includes(b.visual) ? b.visual : 'claro',
  cor: /^#[0-9a-fA-F]{6}$/.test(b.cor || '') ? String(b.cor).toUpperCase() : '', imagens: b.imagens !== false, video: b.video === true,
  voz: VOZES.includes(b.voz) ? b.voz : VOZES[0], legendas: b.legendas !== false, trilha: TRILHAS.includes(b.trilha) ? b.trilha : 'calmo',
};
const erros = [];
if (dados.tema.length < 15) erros.push('Conte sobre o que é a apresentação (pelo menos uma frase).');
// todos os números que o usuário escreveu: gráfico e "números" só podem usar estes (a IA não inventa estatística)
const numeros_usuario = apNumeros(dados.tema + '\n' + dados.conteudo);
const slug = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]+/g, '-').replace(/(^-|-$)/g, '');
let curto = '';   // até 5 palavras inteiras do assunto, no máximo 32 letras
for (const p of slug(dados.tema).split('-').slice(0, 5)) { if ((curto + '-' + p).length > 32) break; curto = curto ? curto + '-' + p : p; }
const id = (curto || 'apresentacao') + '-' + crypto.randomBytes(2).toString('hex');
const chave = crypto.randomBytes(16).toString('hex');
const base = String($('🔔 Pedido da apresentação (POST)').first().json.webhookUrl || '').split('/webhook/')[0];
const hoje = new Date(Date.now() - 3 * 3600000);
const MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];
const resumo_ia = `ASSUNTO E PEDIDO:
${dados.tema}

CONTEÚDO E DADOS DO USUÁRIO (a única fonte de números, nomes, resultados e citações):
${dados.conteudo || '(o usuário não colou conteúdo: use só o assunto acima e conhecimento geral, sem números de pesquisa)'}

PÚBLICO: ${dados.publico || '(não informado)'}
OBJETIVO: ${OBJETIVOS[dados.objetivo]}
TOM: ${TONS[dados.tom]}
QUANTIDADE DE SLIDES: ${op.slides} (com capa e fechamento)
AUTOR: ${dados.autor || '(não informado)'}
CONTATOS PARA O FECHAMENTO: ${dados.contatos.join(' | ') || '(nenhum)'}
IMAGENS: ${op.imagens ? 'sim (marque os slides que ganham imagem)' : 'não'}`;
return [{ json: {
  valido: erros.length === 0, erros, id, chave, dados, op, numeros_usuario, resumo_ia, criado_em: Date.now(),
  data_txt: `${MESES[hoje.getUTCMonth()]} de ${hoje.getUTCFullYear()}`,
  link: `${base}/webhook/apresentacao-ver?id=${id}&chave=${chave}`, apresentar: `${base}/webhook/slides/${id}/apresentar`,
  editar: `${base}/webhook/slides/${id}/apresentar?chave=${chave}`, arquivos: `${base}/videos/arquivo`, base,
  chave_limite: '<SEGREDO_REMOVIDO>' + new Date().toISOString().slice(0, 13),
} }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Desenho dos slides: o MESMO na página de apresentar, no PDF, nas miniaturas e no vídeo (tela de 1920×1080).
const AP_TEMAS = {
  claro: { nome: 'claro', bg: '#FFFFFF', sup: '#F3F5F8', tinta: '#12151B', tinta2: '#4B5361', linha: '#E2E6EC', ft: 'Montserrat', fc: 'Inter', pesoT: 800, cor: '#2563EB' },
  escuro: { nome: 'escuro', bg: '#0E1117', sup: '#1A1E27', tinta: '#F4F6F9', tinta2: '#A9B2C0', linha: '#2C323D', ft: 'Montserrat', fc: 'Inter', pesoT: 800, cor: '#38BDF8' },
  elegante: { nome: 'elegante', bg: '#FAF7F2', sup: '#F1EADF', tinta: '#1E1A15', tinta2: '#5F574C', linha: '#E3D9C9', ft: 'Playfair Display', fc: 'Inter', pesoT: 700, cor: '#8C5A2B' },
  vibrante: { nome: 'vibrante', bg: '#FFFFFF', sup: '#F6F2FB', tinta: '#16121F', tinta2: '#4E4A57', linha: '#E9E3F1', ft: 'Montserrat', fc: 'Inter', pesoT: 800, cor: '#D6246E' },
  corporativo: { nome: 'corporativo', bg: '#FFFFFF', sup: '#F2F5F9', tinta: '#0B1B33', tinta2: '#46566B', linha: '#DCE3EC', ft: 'Montserrat', fc: 'Inter', pesoT: 700, cor: '#1F5FD1', faixa: '#0B2545' },
};
const AP_LAYOUTS = ['capa', 'secao', 'topicos', 'imagem_texto', 'colunas', 'numeros', 'grafico', 'etapas', 'comparacao', 'citacao', 'fechamento'];
const apHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const apLum = h => apHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const apContraste = (a, b) => { const x = apLum(a), y = apLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const apMistura = (a, b, k) => { const x = apHex(a), y = apHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
// cores do tema + a cor de destaque ajustada para aparecer no fundo (>= 3:1, como texto grande e gráfico)
function apTokens(nome, cor) {
  const t = Object.assign({}, AP_TEMAS[nome] || AP_TEMAS.claro);
  let c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : t.cor;
  const escuro = apLum(t.bg) < 0.2;
  for (let i = 0; i < 14 && apContraste(c, t.bg) < 3; i++) c = apMistura(c, escuro ? '#FFFFFF' : '#000000', 0.12);
  t.cor = c;
  t.corTinta = apContraste('#FFFFFF', c) >= 4.5 ? '#FFFFFF' : '#111111';   // texto em cima da cor
  t.suave = apMistura(c, t.bg, escuro ? 0.8 : 0.87);                        // fundo dos ícones e do lado "depois"
  return t;
}
const apEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

function apCSS(t) {
  return `:root{--bg:${t.bg};--sup:${t.sup};--tinta:${t.tinta};--tinta2:${t.tinta2};--linha:${t.linha};--cor:${t.cor};--corTinta:${t.corTinta};--suave:${t.suave};
--ft:'${t.ft}';--fc:'${t.fc}';--pesoT:${t.pesoT};--faixa:${t.faixa || t.tinta}}
.ap-s{position:relative;width:1920px;height:1080px;overflow:hidden;background:var(--bg);color:var(--tinta);font-family:var(--fc),Inter,system-ui,sans-serif;font-size:36px;line-height:1.35;
-webkit-print-color-adjust:exact;print-color-adjust:exact;text-rendering:optimizeLegibility;-webkit-font-smoothing:antialiased}
.ap-s *{box-sizing:border-box}
.ap-s h1,.ap-s h2,.ap-s h3{font-family:var(--ft),Montserrat,sans-serif;font-weight:var(--pesoT);margin:0;line-height:1.08;letter-spacing:-.015em;text-wrap:balance}
.ap-s p,.ap-s ul,.ap-s blockquote{margin:0;padding:0}.ap-s li{list-style:none}
.ap-s [data-c]{overflow-wrap:anywhere}
.ap-fit{position:absolute;left:120px;right:120px;top:92px;bottom:116px;display:flex;flex-direction:column;font-size:38px;overflow:hidden}
.ap-marca{width:2em;height:.22em;border-radius:.11em;background:var(--cor);margin-bottom:.75em;flex:none}
.ap-h2{font-size:1.7em;margin-bottom:.8em;flex:none}
.ap-rod{position:absolute;left:120px;right:120px;bottom:38px;display:flex;justify-content:space-between;gap:40px;font-size:22px;color:var(--tinta2);font-family:var(--fc),Inter,sans-serif}
.ap-rod span:first-child{white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.ap-ico{flex:none;width:2.4em;height:2.4em;border-radius:50%;background:var(--suave);display:flex;align-items:center;justify-content:center;font-size:1em;line-height:1}
.ap-ico span{font-size:1.2em;font-family:'Noto Color Emoji','Apple Color Emoji','Segoe UI Emoji',sans-serif}
.ap-txt{color:var(--tinta2);line-height:1.45}
/* capa */
.L-capa .ap-fundo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover}
.L-capa .ap-veu{position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,10,14,.88) 0%,rgba(8,10,14,.66) 46%,rgba(8,10,14,.12) 100%)}
.L-capa.com-img{--tinta:#FFFFFF;--tinta2:#E4E8EF;color:#fff}
.L-capa .ap-fit{right:auto;width:1200px;top:150px;bottom:170px;justify-content:flex-end}
.L-capa h1{font-size:2.85em;line-height:1.02}
.L-capa .ap-sub{font-size:1.12em;margin-top:.65em;color:var(--tinta2);line-height:1.35}
.L-capa .ap-autor{position:absolute;left:120px;bottom:70px;font-size:26px;color:var(--tinta2);font-weight:500}
.ap-deco1{position:absolute;right:-200px;top:-220px;width:920px;height:920px;border-radius:50%;background:var(--suave)}
.ap-deco2{position:absolute;right:260px;bottom:-280px;width:560px;height:560px;border-radius:50%;background:var(--cor);opacity:.16}
/* fundos fortes: vibrante usa a cor; corporativo usa a faixa escura */
.T-vibrante.L-capa.sem-img,.T-vibrante.L-secao,.T-vibrante.L-fechamento{background:var(--cor);--tinta:var(--corTinta);--tinta2:var(--corTinta);color:var(--corTinta)}
.T-vibrante.L-capa.sem-img .ap-marca,.T-vibrante.L-secao .ap-marca,.T-vibrante.L-fechamento .ap-marca{background:var(--corTinta)}
.T-vibrante.L-capa.sem-img .ap-deco1{background:var(--corTinta);opacity:.1}.T-vibrante.L-capa.sem-img .ap-deco2{background:var(--corTinta);opacity:.12}
.T-corporativo.L-capa.sem-img,.T-corporativo.L-secao{background:var(--faixa);--tinta:#FFFFFF;--tinta2:#C6D1E2;color:#fff}
.T-corporativo.L-capa.sem-img .ap-deco1{background:#FFFFFF;opacity:.06}
.T-corporativo:not(.L-capa):not(.L-secao):not(.L-fechamento)::before{content:'';position:absolute;left:0;right:0;top:0;height:14px;background:var(--faixa)}
/* seção */
.L-secao{background:var(--sup)}
.L-secao .ap-fit{justify-content:center}
.L-secao .ap-num{font-family:var(--ft),Montserrat,sans-serif;font-weight:var(--pesoT);font-size:5.4em;line-height:1;color:var(--cor);margin-bottom:.12em;letter-spacing:-.03em}
.T-vibrante.L-secao .ap-num,.T-corporativo.L-secao .ap-num{color:inherit;opacity:.88}
.L-secao h2{font-size:2.4em;max-width:1500px}
.L-secao .ap-txt{font-size:.95em;margin-top:.8em;max-width:1300px}
/* tópicos */
.ap-itens{display:grid;gap:1.1em 1.8em;flex:1;min-height:0;align-content:center}
.ap-itens.c2{grid-template-columns:1fr 1fr}
.ap-item{display:flex;gap:.75em;align-items:flex-start}
.ap-item h3{font-size:1.18em;margin:.2em 0 .2em}
.ap-item p{font-size:.94em;color:var(--tinta2);line-height:1.4}
/* imagem + texto */
