// ───── gráfico em SVG (uma série só, uma cor, eixo discreto, rótulo nos valores) ─────
function apNum(v, g, compacto) {
  const casas = (g.valores || []).some(x => Math.round(Number(x)) !== Number(x)) ? 1 : 0;
  const n = Number(v);
  const txt = compacto && Math.abs(n) >= 100000 ? new Intl.NumberFormat('pt-BR', { notation: 'compact', maximumFractionDigits: 1 }).format(n)
    : n.toLocaleString('pt-BR', { minimumFractionDigits: casas, maximumFractionDigits: casas });
  return (g.prefixo || '') + txt + (g.sufixo || '');
}
function apEscala(min, max) {
  const span = (max - min) || Math.abs(max) || 1, p0 = span / 4, mag = Math.pow(10, Math.floor(Math.log10(p0))), r = p0 / mag;
  const passo = (r <= 1 ? 1 : r <= 2 ? 2 : r <= 2.5 ? 2.5 : r <= 5 ? 5 : 10) * mag;
  return { min: Math.floor(min / passo) * passo, max: Math.ceil(max / passo) * passo, passo };
}
function apGrafico(g, t) {
  const n = Math.min((g.rotulos || []).length, (g.valores || []).length);
  const rot = (g.rotulos || []).slice(0, n).map(String), val = (g.valores || []).slice(0, n).map(Number);
  if (n < 2) return '';
  let tipo = ['barras', 'barras_h', 'linha'].includes(g.tipo) ? g.tipo : 'barras';
  if (tipo === 'barras' && (n > 8 || rot.some(r => r.length > 12))) tipo = 'barras_h';
  const W = 1100, H = 640, f = (x, k = 1) => Number(x).toFixed(k);
  const txt = (x, y, s, o = '') => `<text x="${f(x)}" y="${f(y)}" ${o}>${apEsc(s)}</text>`;
  const aria = `role="img" aria-label="${apEsc((g.titulo || 'Gráfico') + ': ' + rot.map((r, i) => r + ' ' + apNum(val[i], g)).join('; '))}"`;
  let o = `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" ${aria} font-family="${apEsc(t.fc)}, Inter, sans-serif">`;
  if (tipo === 'barras_h') {
    const L = Math.min(380, 30 + Math.max(...rot.map(r => r.length)) * 15), R = 170, T = 10, B = 10;
    const lo = Math.min(0, ...val), hi = Math.max(0, ...val), esc = v => L + (v - lo) / ((hi - lo) || 1) * (W - L - R);
    const banda = (H - T - B) / n, bh = Math.min(64, banda * 0.62);
    rot.forEach((r, i) => {
      const y = T + banda * i + (banda - bh) / 2, x0 = esc(0), x1 = esc(val[i]), a = Math.min(x0, x1), w = Math.max(2, Math.abs(x1 - x0)), rr = Math.min(10, w / 2, bh / 2);
      const pos = val[i] >= 0;
      o += `<path d="${pos ? `M${f(a)},${f(y)} h${f(w - rr)} a${rr},${rr} 0 0 1 ${rr},${rr} v${f(bh - 2 * rr)} a${rr},${rr} 0 0 1 -${rr},${rr} h-${f(w - rr)} z`
        : `M${f(a + w)},${f(y)} h-${f(w - rr)} a${rr},${rr} 0 0 0 -${rr},${rr} v${f(bh - 2 * rr)} a${rr},${rr} 0 0 0 ${rr},${rr} h${f(w - rr)} z`}" fill="${t.cor}"><title>${apEsc(r + ': ' + apNum(val[i], g))}</title></path>`;
      o += txt(L - 18, y + bh / 2 + 9, r.length > 26 ? r.slice(0, 25) + '…' : r, `text-anchor="end" font-size="26" fill="${t.tinta}"`);
      o += txt(pos ? x1 + 14 : x1 - 14, y + bh / 2 + 10, apNum(val[i], g), `text-anchor="${pos ? 'start' : 'end'}" font-size="28" font-weight="700" fill="${t.tinta}"`);
    });
    o += `<line x1="${f(esc(0))}" x2="${f(esc(0))}" y1="${T}" y2="${H - B}" stroke="${t.tinta2}" stroke-width="2"/>`;
    return o + '</svg>';
  }
  const L = 96, R = 24, T = 52, B = 64;
  const e = apEscala(Math.min(0, ...val), Math.max(0, ...val));
  const y = v => T + (e.max - v) / ((e.max - e.min) || 1) * (H - T - B);
  for (let v = e.min; v <= e.max + e.passo / 2; v += e.passo) {
    o += `<line x1="${L}" x2="${W - R}" y1="${f(y(v))}" y2="${f(y(v))}" stroke="${Math.abs(v) < e.passo / 1e6 ? t.tinta2 : t.linha}" stroke-width="2"/>`;
    o += txt(L - 14, y(v) + 8, apNum(v, { valores: g.valores }, true), `text-anchor="end" font-size="22" fill="${t.tinta2}"`);
  }
  const banda = (W - L - R) / n, cx = i => L + banda * i + banda / 2, pula = Math.ceil(n / 8);
  rot.forEach((r, i) => { if (i % pula === 0 || i === n - 1) o += txt(cx(i), H - B + 40, r.length > 14 ? r.slice(0, 13) + '…' : r, `text-anchor="middle" font-size="25" fill="${t.tinta2}"`); });
  if (tipo === 'linha') {
    const pts = val.map((v, i) => [cx(i), y(v)]);
    o += `<path d="M${pts.map(p => f(p[0]) + ',' + f(p[1])).join(' L')} L${f(pts[n - 1][0])},${f(y(Math.max(e.min, 0)))} L${f(pts[0][0])},${f(y(Math.max(e.min, 0)))} z" fill="${t.cor}" opacity=".10"/>`;
    o += `<path d="M${pts.map(p => f(p[0]) + ',' + f(p[1])).join(' L')}" fill="none" stroke="${t.cor}" stroke-width="6" stroke-linejoin="round" stroke-linecap="round"/>`;
    const imax = val.indexOf(Math.max(...val)), imin = val.indexOf(Math.min(...val));
    pts.forEach((p, i) => {
      o += `<circle cx="${f(p[0])}" cy="${f(p[1])}" r="10" fill="${t.cor}" stroke="${t.bg}" stroke-width="4"><title>${apEsc(rot[i] + ': ' + apNum(val[i], g))}</title></circle>`;
      if (i === 0 || i === n - 1 || i === imax || i === imin) o += txt(p[0], p[1] - 22, apNum(val[i], g), `text-anchor="middle" font-size="28" font-weight="700" fill="${t.tinta}"`);
    });
  } else {
    const bw = Math.min(120, banda * 0.62);
    val.forEach((v, i) => {
      const x = cx(i) - bw / 2, y0 = y(0), y1 = y(v), h = Math.max(2, Math.abs(y1 - y0)), rr = Math.min(10, bw / 2, h / 2), pos = v >= 0;
      o += `<path d="${pos ? `M${f(x)},${f(y0)} v-${f(h - rr)} a${rr},${rr} 0 0 1 ${rr},-${rr} h${f(bw - 2 * rr)} a${rr},${rr} 0 0 1 ${rr},${rr} v${f(h - rr)} z`
        : `M${f(x)},${f(y0)} v${f(h - rr)} a${rr},${rr} 0 0 0 ${rr},${rr} h${f(bw - 2 * rr)} a${rr},${rr} 0 0 0 ${rr},-${rr} v-${f(h - rr)} z`}" fill="${t.cor}"><title>${apEsc(rot[i] + ': ' + apNum(v, g))}</title></path>`;
      o += txt(cx(i), pos ? y1 - 16 : y1 + 36, apNum(v, g), `text-anchor="middle" font-size="28" font-weight="700" fill="${t.tinta}"`);
    });
  }
  return o + '</svg>';
}

// ───── um slide ─────  (data-c = campo editável pelo dono: "<slide>.<campo>")
function apSlide(d, s, i, base) {
  const t = d.t, total = d.slides.length, lay = AP_LAYOUTS.includes(s.layout) ? s.layout : 'topicos';
  const E = (campo, tag, cls, valor) => `<${tag}${cls ? ` class="${cls}"` : ''} data-c="${i}.${campo}">${apEsc(valor)}</${tag}>`;
  const img = s.imagem && s.imagem.arquivo ? `${base}/${s.imagem.arquivo}` : '';
  const foco = s.imagem && s.imagem.foco ? `${Math.round((+s.imagem.foco.x || 0.5) * 100)}% ${Math.round((+s.imagem.foco.y || 0.5) * 100)}%` : '50% 50%';
  const alt = s.imagem && s.imagem.alt ? apEsc(s.imagem.alt) : '';
  const titulo = (cls = 'ap-h2') => `<div class="ap-marca"></div>${E('titulo', 'h2', cls, s.titulo)}`;
  const itens = (lst, icones = true) => (lst || []).map((it, k) => `<li class="ap-item">${icones ? `<div class="ap-ico"><span>${apEsc(it.icone || '•')}</span></div>` : ''}<div>${E(`itens.${k}.t`, 'h3', '', it.t)}${it.d ? E(`itens.${k}.d`, 'p', '', it.d) : ''}</div></li>`).join('');
  const rod = `<div class="ap-rod"><span>${apEsc(d.titulo)}</span><span>${i + 1} / ${total}</span></div>`;
  let cls = '', corpo = '', comRod = true;
  if (lay === 'capa') {
    comRod = false;
    corpo = (img ? `<img class="ap-fundo" src="${img}" alt="${alt}" style="object-position:${foco}"><div class="ap-veu"></div>` : '<div class="ap-deco1"></div><div class="ap-deco2"></div>')
      + `<div class="ap-fit"><div class="ap-marca"></div>${E('titulo', 'h1', '', s.titulo)}${s.subtitulo ? E('subtitulo', 'p', 'ap-sub', s.subtitulo) : ''}</div>`
      + `<p class="ap-autor">${apEsc([d.autor, d.data_txt].filter(Boolean).join(' · '))}</p>`;
  } else if (lay === 'secao') {
    comRod = false;
    const num = d.slides.slice(0, i + 1).filter(x => x.layout === 'secao').length;
    corpo = `<div class="ap-fit"><div class="ap-num">${String(num).padStart(2, '0')}</div>${E('titulo', 'h2', '', s.titulo)}${s.texto ? E('texto', 'p', 'ap-txt', s.texto) : ''}</div>`;
  } else if (lay === 'imagem_texto') {
    cls = i % 2 ? '' : 'esq';
    corpo = (img ? `<img class="ap-img" src="${img}" alt="${alt}" style="object-position:${foco}">` : '')
      + `<div class="ap-fit">${titulo()}<div class="ap-corpo ap-cresce">${(s.itens || []).length ? `<ul class="ap-itens">${itens(s.itens)}</ul>` : E('texto', 'p', 'ap-txt', s.texto)}</div></div>`;
  } else if (lay === 'colunas') {
    corpo = `<div class="ap-fit">${titulo()}<div class="ap-cols ap-cresce">${(s.itens || []).map((it, k) => `<div class="ap-card"><div class="ap-ico"><span>${apEsc(it.icone || '•')}</span></div>${E(`itens.${k}.t`, 'h3', '', it.t)}${E(`itens.${k}.d`, 'p', '', it.d)}</div>`).join('')}</div></div>`;
  } else if (lay === 'numeros') {
    const ns = s.numeros || [], larg = (1680 - 40 * (ns.length - 1)) / Math.max(1, ns.length) / 36 - 2.5;
    corpo = `<div class="ap-fit">${titulo()}<div class="ap-nums">${ns.map((x, k) => {
      const fs = Math.max(1.4, Math.min(3.1, larg / (Math.max(3, String(x.v || '').length) * 0.6)));
      return `<div class="ap-numc"><div class="v" style="font-size:${fs.toFixed(2)}em" data-c="${i}.numeros.${k}.v">${apEsc(x.v)}</div>${E(`numeros.${k}.r`, 'div', 'r', x.r)}${x.d ? E(`numeros.${k}.d`, 'div', 'd', x.d) : ''}</div>`;
    }).join('')}</div></div>`;
  } else if (lay === 'grafico') {
    const g = s.grafico || {};
    corpo = `<div class="ap-fit">${titulo()}<div class="ap-gw"><div class="ap-g">${g.titulo ? `<div class="gt">${apEsc(g.titulo)}</div>` : ''}${apGrafico(g, t)}</div>`
      + `<div class="ap-ins">${s.destaque ? E('destaque', 'p', 'big', s.destaque) : ''}${g.fonte ? `<p class="fonte">Fonte: ${apEsc(g.fonte)}</p>` : ''}</div></div></div>`;
  } else if (lay === 'etapas') {
    corpo = `<div class="ap-fit">${titulo()}<div class="ap-etapas ap-cresce">${(s.itens || []).map((it, k) => `<div class="ap-etapa"><div class="n">${k + 1}</div>${E(`itens.${k}.t`, 'h3', '', it.t)}${it.d ? E(`itens.${k}.d`, 'p', '', it.d) : ''}</div>`).join('')}</div></div>`;
  } else if (lay === 'comparacao') {
    const c = s.comparacao || {};
    const lado = (k, marca) => `<div class="ap-lado ${k}">${E(`comparacao.${k}.titulo`, 'h3', '', (c[k] || {}).titulo)}<ul>${((c[k] || {}).itens || []).map((x, j) => `<li><i>${marca}</i>${E(`comparacao.${k}.itens.${j}`, 'span', '', x)}</li>`).join('')}</ul></div>`;
    corpo = `<div class="ap-fit">${titulo()}<div class="ap-comp ap-cresce">${lado('a', '•')}${lado('b', '✓')}</div></div>`;
  } else if (lay === 'citacao') {
    comRod = false;
    const c = s.citacao || {};
    corpo = (img ? `<img class="ap-fundo" src="${img}" alt="" style="object-position:${foco}">` : '')
      + `<div class="ap-fit"><div class="aspas">“</div>${E('citacao.texto', 'blockquote', '', c.texto)}${c.autor ? `<p class="autor">— <span data-c="${i}.citacao.autor">${apEsc(c.autor)}</span></p>` : ''}</div>`;
  } else if (lay === 'fechamento') {
    comRod = false;
    const qr = d.qr ? `${base}/${d.qr}` : '';
    cls = qr ? 'com-qr' : '';
    corpo = `<div class="ap-fit"><div class="ap-marca"></div>${E('titulo', 'h2', '', s.titulo)}${s.texto ? E('texto', 'p', 'ap-txt', s.texto) : ''}`
      + `${(d.contatos || []).length ? `<div class="ap-cont">${d.contatos.map(x => `<span>${apEsc(x)}</span>`).join('')}</div>` : ''}</div>`
      + (qr ? `<div class="ap-qr"><img src="${qr}" alt="QR code para abrir esta apresentação"><p>Aponte a câmera para baixar a apresentação</p></div>` : '');
  } else {   // tópicos
    const lst = s.itens || [];
    corpo = `<div class="ap-fit">${titulo()}${lst.length ? `<ul class="ap-itens ap-cresce${lst.length >= 4 ? ' c2' : ''}">${itens(lst)}</ul>` : E('texto', 'p', 'ap-txt ap-cresce', s.texto)}</div>`;
  }
  return `<section class="ap-s L-${lay} T-${t.nome} ${img ? 'com-img' : 'sem-img'} ${cls}" data-i="${i}" aria-label="Slide ${i + 1} de ${total}">${corpo}${comRod ? rod : ''}</section>`;
}

// diminui a letra do bloco de texto que não coube (roda na página e no Chromium que faz o PDF)
// o corpo (.ap-cresce) começa 22% maior e desce até caber; sem corpo marcado, o bloco todo só diminui
const AP_AJUSTA = `function apAjusta(raiz){(raiz||document).querySelectorAll('.ap-fit').forEach(function(el){
var alvo=el.querySelector('.ap-cresce')||el,b=parseFloat(alvo.getAttribute('data-base')||'');if(!b){b=parseFloat(getComputedStyle(alvo).fontSize)||36;alvo.setAttribute('data-base',b);}
var f=alvo===el?1:1.22;alvo.style.fontSize=(b*f)+'px';while(f>0.6&&(el.scrollHeight>el.clientHeight+2||el.scrollWidth>el.clientWidth+2)){f-=0.04;alvo.style.fontSize=(b*f)+'px';}});}`;

// documento para o PDF: um slide por página de 1920×1080
function apDocumento(d, base) {
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${apEsc(d.titulo)}</title><style>${apCSS(d.t)}
@page{size:1920px 1080px;margin:0}html,body{margin:0;padding:0;background:${d.t.bg}}.ap-s{break-after:page;page-break-after:always}.ap-s:last-child{break-after:auto;page-break-after:auto}</style></head>
<body>${d.slides.map((s, i) => apSlide(d, s, i, base)).join('')}<script>${AP_AJUSTA}
(document.fonts&&document.fonts.ready?document.fonts.ready:Promise.resolve()).then(function(){apAjusta(document);document.body.setAttribute('data-pronto','1');});</script></body></html>`;
}

// Regras do conteúdo dos slides (iguais na redatora, na revisora e na edição do dono).
const apT = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const apEmoji = (v, k) => { const m = String(v || '').match(/\p{Extended_Pictographic}(️|‍\p{Extended_Pictographic})*/u); return m ? m[0] : ['💡', '✅', '🎯', '🚀', '📌'][k % 5]; };
// todos os números de um texto ("R$ 48 mil" = 48 e 48000; "1.240" = 1240; "4,5" = 4.5)
function apNumeros(t) {
  const out = [], s0 = String(t || ''), re = /\d[\d.,]*/g;
  let m;
  while ((m = re.exec(s0))) {
    const s = m[0].replace(/[.,]+$/, ''), depois = s0.slice(m.index + m[0].length, m.index + m[0].length + 12).toLowerCase();
    const mult = /^\s*(mil\b|k\b)/.test(depois) ? 1e3 : /^\s*(milh|mi\b)/.test(depois) ? 1e6 : /^\s*(bilh|bi\b)/.test(depois) ? 1e9 : 1;
    for (const v of [Number(s.replace(/\./g, '').replace(',', '.')), Number(s.replace(/,/g, ''))]) {
      if (isFinite(v)) { out.push(v); if (mult > 1) out.push(v * mult); }
    }
  }
  return [...new Set(out)];
}
const apConfere = (v, lista) => lista.some(x => Math.abs(x - v) <= Math.max(0.011, Math.abs(x) * 0.005));
const apNumeroDoGrafico = v => typeof v === 'number' ? v : Number(String(v ?? '').replace(/[^\d,.\-]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.'));
// só os campos do layout, com tamanho máximo e listas na quantidade certa
function apSaneia(s, layout) {
  s = s || {};
  const o = { n: s.n, layout, titulo: apT(s.titulo, 90), notas: apT(s.notas, 600), narracao: apT(s.narracao, 700).replace(/\p{Extended_Pictographic}/gu, '').trim() };
  const itens = (max, lt, ld, ico = true) => (Array.isArray(s.itens) ? s.itens : []).map((it, k) => ({
    icone: ico ? apEmoji(it && it.icone, k) : '', t: apT(it && (typeof it === 'string' ? it : it.t || it.titulo), lt), d: apT(it && (it.d || it.texto || it.descricao), ld) })).filter(it => it.t).slice(0, max);
  if (layout === 'capa') o.subtitulo = apT(s.subtitulo, 140);
  else if (layout === 'secao') o.texto = apT(s.texto, 160);
  else if (layout === 'topicos') { o.itens = itens(5, 48, 130); if (o.itens.length < 2) { o.texto = apT(s.texto || o.itens.map(i => i.t + (i.d ? ': ' + i.d : '')).join(' · ') || s.notas, 400); o.itens = []; } }
  else if (layout === 'imagem_texto') { o.texto = apT(s.texto, 360); o.itens = o.texto ? [] : itens(3, 44, 110); }
  else if (layout === 'colunas') o.itens = itens(4, 36, 150);
  else if (layout === 'etapas') o.itens = itens(5, 32, 110, false);
  else if (layout === 'numeros') o.numeros = (Array.isArray(s.numeros) ? s.numeros : []).map(x => ({ v: apT(x && x.v, 14), r: apT(x && x.r, 40), d: apT(x && x.d, 90) })).filter(x => x.v && x.r).slice(0, 4);
  else if (layout === 'grafico') {
    const g = s.grafico || {}, n = Math.min((g.rotulos || []).length, (g.valores || []).length, 12);
    o.destaque = apT(s.destaque, 140);
    // "R$" + 39 + "mil" vira "R$ 39 mil" (o % fica colado: "23%")
    const pre = apT(g.prefixo, 6), suf = apT(g.sufixo, 10);
    o.grafico = { tipo: ['barras', 'barras_h', 'linha'].includes(g.tipo) ? g.tipo : 'barras', titulo: apT(g.titulo, 60), rotulos: (g.rotulos || []).slice(0, n).map(x => apT(x, 30)),
      valores: (g.valores || []).slice(0, n).map(apNumeroDoGrafico), prefixo: pre ? pre + ' ' : '', sufixo: /^[A-Za-zÀ-ú]/.test(suf) ? ' ' + suf : suf, fonte: apT(g.fonte, 80) };
  } else if (layout === 'comparacao') {
    const c = s.comparacao || {}, lado = x => ({ titulo: apT(x && x.titulo, 26), itens: (Array.isArray(x && x.itens) ? x.itens : []).map(i => apT(typeof i === 'string' ? i : i && (i.t || i.texto), 90)).filter(Boolean).slice(0, 5) });
    o.comparacao = { a: lado(c.a), b: lado(c.b) };
  } else if (layout === 'citacao') { const c = s.citacao || {}; o.citacao = { texto: apT(c.texto || s.texto, 240), autor: apT(c.autor, 70) }; }
  else if (layout === 'fechamento') o.texto = apT(s.texto, 180);
  return apEstrutura(o);
}
// o que não dá para mostrar no layout pedido vira tópicos (lista vazia, gráfico sem números, comparação com um lado só)
function apEstrutura(o) {
  const vira = (itens, texto) => Object.assign({ n: o.n, layout: 'topicos', titulo: o.titulo, notas: o.notas, narracao: o.narracao }, itens.length >= 2 ? { itens } : { itens: [], texto: apT(texto || o.notas, 400) });
  if (o.layout === 'grafico' && !(o.grafico.valores.length >= 2 && o.grafico.valores.every(v => isFinite(v)))) return vira([], o.destaque);
  if (o.layout === 'numeros' && o.numeros.length < 2) return vira(o.numeros.map((x, k) => ({ icone: apEmoji('', k), t: x.v + ' ' + x.r, d: x.d })), '');
  if ((o.layout === 'colunas' || o.layout === 'etapas') && o.itens.length < 2) return vira(o.itens.map((x, k) => ({ icone: apEmoji(x.icone, k), t: x.t, d: x.d })), '');
  if (o.layout === 'comparacao' && !(o.comparacao.a.itens.length && o.comparacao.b.itens.length)) {
    const it = o.comparacao.a.itens.concat(o.comparacao.b.itens).map((t, k) => ({ icone: apEmoji('', k), t, d: '' }));
    return vira(it, '');
  }
  if (o.layout === 'citacao' && !o.citacao.texto) return vira([], o.notas);
  if (o.layout === 'fechamento' && !o.titulo) o.titulo = 'Obrigado!';
  return o;
}
// números do slide que não estão nos dados do usuário (gráfico e "números")
function apNumerosFora(o, lista) {
  if (o.layout === 'grafico') return o.grafico.valores.filter(v => !apConfere(v, lista)).map(v => String(v).replace('.', ','));
  if (o.layout === 'numeros') return o.numeros.filter(x => !apNumeros(x.v).some(v => apConfere(v, lista))).map(x => x.v);
  return [];
}
// tira os números que não vieram do usuário (o slide continua, sem eles)
function apSemNumeros(o, lista) {
  if (o.layout === 'numeros') {
    const bons = o.numeros.filter(x => apNumeros(x.v).some(v => apConfere(v, lista)));
    return apEstrutura(Object.assign({}, o, { numeros: bons }));
  }
  if (o.layout === 'grafico') return apEstrutura(Object.assign({}, o, { grafico: Object.assign({}, o.grafico, { valores: [] }) }));
  return o;
}

// Confere os slides da redatora: um por item do plano, no layout do plano, com os tamanhos e as listas certas.
// Também separa os números que não estão nos dados do usuário (a revisora corrige; o que sobrar sai no fim).
const V = $('🧩 Confere o pedido').first().json, P = $('🧩 Lê o plano').first().json;
let r = null;
try { r = parseJSON($('🤖 Redatora dos slides').first().json.output); } catch (e) {}
const lst = r && Array.isArray(r.slides) ? r.slides : [];
const ultimo = P.plano.length - 1;
const slides = P.plano.map((pl, i) => {
  const s = lst.find(x => Number(x && x.n) === pl.n) || lst[i] || {};
  // se a redatora trocou o layout no meio, vale o dela (o conteúdo foi escrito para ele); capa e fechamento ficam
  const lay = i > 0 && i < ultimo && AP_LAYOUTS.includes(s.layout) && !['capa', 'fechamento'].includes(s.layout) ? s.layout : pl.layout;
  return apSaneia(Object.assign({}, s, { n: pl.n }), lay);
});
const comTexto = slides.filter(s => s.titulo || (s.citacao && s.citacao.texto)).length;
const ok = lst.length > 0 && comTexto >= Math.ceil(slides.length * 0.6);
const fora = slides.flatMap(s => apNumerosFora(s, V.numeros_usuario).map(x => `slide ${s.n}: ${x}`));
const texto_revisora = `DADOS DO USUÁRIO (a única fonte de verdade):
${V.resumo_ia}

NÚMEROS QUE O USUÁRIO ESCREVEU: ${V.numeros_usuario.slice(0, 80).map(x => String(x).replace('.', ',')).join(' · ') || 'nenhum'}
NÚMEROS DOS SLIDES QUE NÃO APARECEM NOS DADOS (corrija ou tire): ${fora.join(' | ') || 'nenhum'}

SLIDES DA REDATORA (JSON):
${JSON.stringify(slides)}`;
return [{ json: { ok, slides, fora, texto_revisora, palavras: slides.reduce((a, s) => a + s.narracao.split(/\s+/).filter(Boolean).length, 0),
  erro: ok ? '' : 'A IA redatora não devolveu os slides agora. Tente de novo.' } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Regras do conteúdo dos slides (iguais na redatora, na revisora e na edição do dono).
const apT = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const apEmoji = (v, k) => { const m = String(v || '').match(/\p{Extended_Pictographic}(️|‍\p{Extended_Pictographic})*/u); return m ? m[0] : ['💡', '✅', '🎯', '🚀', '📌'][k % 5]; };
// todos os números de um texto ("R$ 48 mil" = 48 e 48000; "1.240" = 1240; "4,5" = 4.5)
function apNumeros(t) {
  const out = [], s0 = String(t || ''), re = /\d[\d.,]*/g;
  let m;
  while ((m = re.exec(s0))) {
    const s = m[0].replace(/[.,]+$/, ''), depois = s0.slice(m.index + m[0].length, m.index + m[0].length + 12).toLowerCase();
    const mult = /^\s*(mil\b|k\b)/.test(depois) ? 1e3 : /^\s*(milh|mi\b)/.test(depois) ? 1e6 : /^\s*(bilh|bi\b)/.test(depois) ? 1e9 : 1;
    for (const v of [Number(s.replace(/\./g, '').replace(',', '.')), Number(s.replace(/,/g, ''))]) {
      if (isFinite(v)) { out.push(v); if (mult > 1) out.push(v * mult); }
    }
  }
  return [...new Set(out)];
}
const apConfere = (v, lista) => lista.some(x => Math.abs(x - v) <= Math.max(0.011, Math.abs(x) * 0.005));
const apNumeroDoGrafico = v => typeof v === 'number' ? v : Number(String(v ?? '').replace(/[^\d,.\-]/g, '').replace(/\.(?=\d{3}(\D|$))/g, '').replace(',', '.'));
// só os campos do layout, com tamanho máximo e listas na quantidade certa
function apSaneia(s, layout) {
  s = s || {};
  const o = { n: s.n, layout, titulo: apT(s.titulo, 90), notas: apT(s.notas, 600), narracao: apT(s.narracao, 700).replace(/\p{Extended_Pictographic}/gu, '').trim() };
  const itens = (max, lt, ld, ico = true) => (Array.isArray(s.itens) ? s.itens : []).map((it, k) => ({
    icone: ico ? apEmoji(it && it.icone, k) : '', t: apT(it && (typeof it === 'string' ? it : it.t || it.titulo), lt), d: apT(it && (it.d || it.texto || it.descricao), ld) })).filter(it => it.t).slice(0, max);
  if (layout === 'capa') o.subtitulo = apT(s.subtitulo, 140);
  else if (layout === 'secao') o.texto = apT(s.texto, 160);
  else if (layout === 'topicos') { o.itens = itens(5, 48, 130); if (o.itens.length < 2) { o.texto = apT(s.texto || o.itens.map(i => i.t + (i.d ? ': ' + i.d : '')).join(' · ') || s.notas, 400); o.itens = []; } }
  else if (layout === 'imagem_texto') { o.texto = apT(s.texto, 360); o.itens = o.texto ? [] : itens(3, 44, 110); }
  else if (layout === 'colunas') o.itens = itens(4, 36, 150);
  else if (layout === 'etapas') o.itens = itens(5, 32, 110, false);
  else if (layout === 'numeros') o.numeros = (Array.isArray(s.numeros) ? s.numeros : []).map(x => ({ v: apT(x && x.v, 14), r: apT(x && x.r, 40), d: apT(x && x.d, 90) })).filter(x => x.v && x.r).slice(0, 4);
  else if (layout === 'grafico') {
    const g = s.grafico || {}, n = Math.min((g.rotulos || []).length, (g.valores || []).length, 12);
    o.destaque = apT(s.destaque, 140);
    // "R$" + 39 + "mil" vira "R$ 39 mil" (o % fica colado: "23%")
    const pre = apT(g.prefixo, 6), suf = apT(g.sufixo, 10);
    o.grafico = { tipo: ['barras', 'barras_h', 'linha'].includes(g.tipo) ? g.tipo : 'barras', titulo: apT(g.titulo, 60), rotulos: (g.rotulos || []).slice(0, n).map(x => apT(x, 30)),
      valores: (g.valores || []).slice(0, n).map(apNumeroDoGrafico), prefixo: pre ? pre + ' ' : '', sufixo: /^[A-Za-zÀ-ú]/.test(suf) ? ' ' + suf : suf, fonte: apT(g.fonte, 80) };
  } else if (layout === 'comparacao') {
    const c = s.comparacao || {}, lado = x => ({ titulo: apT(x && x.titulo, 26), itens: (Array.isArray(x && x.itens) ? x.itens : []).map(i => apT(typeof i === 'string' ? i : i && (i.t || i.texto), 90)).filter(Boolean).slice(0, 5) });
    o.comparacao = { a: lado(c.a), b: lado(c.b) };
  } else if (layout === 'citacao') { const c = s.citacao || {}; o.citacao = { texto: apT(c.texto || s.texto, 240), autor: apT(c.autor, 70) }; }
  else if (layout === 'fechamento') o.texto = apT(s.texto, 180);
  return apEstrutura(o);
}
// o que não dá para mostrar no layout pedido vira tópicos (lista vazia, gráfico sem números, comparação com um lado só)
function apEstrutura(o) {
  const vira = (itens, texto) => Object.assign({ n: o.n, layout: 'topicos', titulo: o.titulo, notas: o.notas, narracao: o.narracao }, itens.length >= 2 ? { itens } : { itens: [], texto: apT(texto || o.notas, 400) });
  if (o.layout === 'grafico' && !(o.grafico.valores.length >= 2 && o.grafico.valores.every(v => isFinite(v)))) return vira([], o.destaque);
  if (o.layout === 'numeros' && o.numeros.length < 2) return vira(o.numeros.map((x, k) => ({ icone: apEmoji('', k), t: x.v + ' ' + x.r, d: x.d })), '');
  if ((o.layout === 'colunas' || o.layout === 'etapas') && o.itens.length < 2) return vira(o.itens.map((x, k) => ({ icone: apEmoji(x.icone, k), t: x.t, d: x.d })), '');
  if (o.layout === 'comparacao' && !(o.comparacao.a.itens.length && o.comparacao.b.itens.length)) {
    const it = o.comparacao.a.itens.concat(o.comparacao.b.itens).map((t, k) => ({ icone: apEmoji('', k), t, d: '' }));
    return vira(it, '');
  }
  if (o.layout === 'citacao' && !o.citacao.texto) return vira([], o.notas);
  if (o.layout === 'fechamento' && !o.titulo) o.titulo = 'Obrigado!';
  return o;
}
// números do slide que não estão nos dados do usuário (gráfico e "números")
function apNumerosFora(o, lista) {
  if (o.layout === 'grafico') return o.grafico.valores.filter(v => !apConfere(v, lista)).map(v => String(v).replace('.', ','));
  if (o.layout === 'numeros') return o.numeros.filter(x => !apNumeros(x.v).some(v => apConfere(v, lista))).map(x => x.v);
  return [];
}
// tira os números que não vieram do usuário (o slide continua, sem eles)
function apSemNumeros(o, lista) {
  if (o.layout === 'numeros') {
    const bons = o.numeros.filter(x => apNumeros(x.v).some(v => apConfere(v, lista)));
    return apEstrutura(Object.assign({}, o, { numeros: bons }));
  }
  if (o.layout === 'grafico') return apEstrutura(Object.assign({}, o, { grafico: Object.assign({}, o.grafico, { valores: [] }) }));
  return o;
}

// Aplica a revisão: troca só os slides que a revisora devolveu (no mesmo layout). Trava final: número de gráfico
// ou de "números" que ainda não está nos dados do usuário sai do slide. Prepara o pedido da diretora de arte.
const V = $('🧩 Confere o pedido').first().json, P = $('🧩 Lê o plano').first().json, C = $('🧩 Confere os slides').first().json;
let r = null;
try { r = parseJSON($('🤖 Revisora dos slides').first().json.output); } catch (e) {}
const novos = r && Array.isArray(r.slides) ? r.slides : [];
let trocados = 0;
let slides = C.slides.map(s => {
  const x = novos.find(y => Number(y && y.n) === s.n);
  if (!x) return s;
  const o = apSaneia(Object.assign({}, x, { n: s.n }), s.layout);
  if (!o.titulo && s.titulo && s.layout !== 'citacao') return s;   // revisão quebrada: fica o da redatora
  trocados++;
  return o;
});
const problemas = (r && Array.isArray(r.problemas) ? r.problemas : []).map(p => apT(p, 220)).filter(Boolean).slice(0, 8);
slides = slides.map(s => {
  const fora = apNumerosFora(s, V.numeros_usuario);
  if (!fora.length) return s;
  problemas.push(`Slide ${s.n}: ${s.layout === 'grafico' ? 'gráfico tirado' : 'números tirados'} (${fora.join(', ')} não está nos seus dados)`);
  return apSemNumeros(s, V.numeros_usuario);
});
const comImagem = slides.filter((s, i) => P.plano[i] && P.plano[i].imagem && ['capa', 'imagem_texto', 'citacao'].includes(s.layout));   // só layout que mostra foto
const resumo = s => [s.titulo, s.subtitulo, s.texto, (s.itens || []).map(i => i.t).join(', '), s.citacao && s.citacao.texto].filter(Boolean).join(' — ').slice(0, 300);
const texto_arte = `ASSUNTO: ${V.dados.tema.slice(0, 600)}
PÚBLICO: ${V.dados.publico || '(geral)'} · OBJETIVO: ${V.dados.objetivo} · TOM: ${V.dados.tom}
TEMA VISUAL DOS SLIDES: ${V.op.visual}${V.op.cor ? ' · cor escolhida pelo usuário: ' + V.op.cor : ''}
ESTILO SUGERIDO PELA PLANEJADORA: ${P.estilo || '(escolha você)'}

SLIDES QUE VÃO GANHAR IMAGEM:
${comImagem.map(s => `${s.n}. ${s.layout}: ${resumo(s)}`).join('\n') || '(nenhum)'}`;
return [{ json: { slides, problemas, trocados, revisou: !!r, com_imagem: comImagem.map(s => s.n), texto_arte, imagens: V.op.imagens && comImagem.length > 0 } }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Um pedido de imagem por slide que leva foto (prompt da diretora de arte; sem ela, um prompt simples pelo título).
// Sem nenhuma imagem: sai 1 item "pular" (o fluxo segue direto para a montagem).
const V = $('🧩 Confere o pedido').first().json, R = $('🧩 Aplica a revisão').first().json;
let a = null;
try { a = parseJSON($('🤖 Diretora de arte').first().json.output); } catch (e) {}
a = a || {};
const lista = Array.isArray(a.imagens) ? a.imagens : [];
const estilo = String(a.estilo || 'clean editorial photography, soft natural light, realistic').slice(0, 200);
const FIM = ' Wide landscape composition, full-bleed (no border, no frame, no white margin). Absolutely no text, no letters, no numbers, no logos, no watermark.';
const itens = R.com_imagem.map(n => {
  const s = R.slides.find(x => x.n === n) || {};
  const x = lista.find(y => Number(y && y.n) === n) || {};
  const base = String(x.prompt || `${s.titulo || V.dados.tema.slice(0, 120)}, illustrative image for a presentation slide`).replace(/\s+/g, ' ').slice(0, 900);
  const foco = x.foco && isFinite(x.foco.x) && isFinite(x.foco.y) ? { x: Math.min(1, Math.max(0, +x.foco.x)), y: Math.min(1, Math.max(0, +x.foco.y)) } : { x: 0.5, y: 0.5 };
  return { n, nome: 'img-' + String(n).padStart(2, '0'), prompt: base + (base.toLowerCase().includes(estilo.toLowerCase().slice(0, 20)) ? '' : ' Style: ' + estilo + '.') + FIM,
    foco, alt: String(x.alt || s.titulo || '').slice(0, 160) };
});
if (!itens.length) return [{ json: { pular: true } }];
return itens.map(i => ({ json: i }));

// Junta as imagens que a IA desenhou (uma por pedido, na mesma ordem) num pedido só para a oficina guardar.
