const refazer = [];
for (const p of pedidos) {
  const nota = notas.find(x => x && x.nome === p.nome);
  if (!guardadas.includes(p.nome)) refazer.push({ ...p, motivo: 'não veio', nome: p.nome + '-r1' });
  else if (nota && nota.ok === false) refazer.push({ ...p, motivo: String(nota.problema || 'defeito').slice(0, 120), nome: p.nome + '-r1',
    prompt: p.prompt + ' Avoid this problem from the previous attempt: ' + String(nota.problema || 'visual defects').slice(0, 120) + '.' });
}
const reprovadas = notas.filter(x => x && x.ok === false).map(x => ({ nome: x.nome, problema: String(x.problema || '').slice(0, 120) }));
if (!refazer.length) return [{ json: { refazer: false, viu: !!v, reprovadas } }];
return refazer.slice(0, 5).map(x => ({ json: { ...x, refazer: true, viu: !!v, reprovadas } }));

