const g1 = (tenta(() => $('🛠️ Oficina: guarda as imagens').first().json.imagens) || []);
const rev = tenta(() => $('🧩 Lê a revisão das imagens').all().map(i => i.json)) || [];
const g2 = (tenta(() => $('🛠️ Oficina: guarda as refeitas').first().json.imagens) || []);
const reprovadas = new Set(((rev[0] || {}).reprovadas || []).map(x => x.nome));
const final = {}, relato = { pedidas: pedidos.length, aprovadas: 0, refeitas: 0, sem: 0, reprovadas: [...reprovadas] };
for (const p of pedidos) {
  const orig = g1.find(g => g.nome === p.nome), nova = g2.find(g => g.nome === p.nome + '-r1');
  const usa = nova || (orig && !reprovadas.has(p.nome) ? orig : null);
  if (usa) { final[p.n] = { arquivo: usa.arquivo, foco: p.foco, alt: p.alt }; if (nova) relato.refeitas++; else relato.aprovadas++; } else relato.sem++;
}
const cor = V.op.cor || (/^#[0-9a-fA-F]{6}$/.test(arte.cor || '') ? String(arte.cor).toUpperCase() : '') || P.cor || '';
const slides = R.slides.map(s => final[s.n] ? Object.assign({}, s, { imagem: final[s.n] }) : s);
// o fechamento já mostra os contatos embaixo: tira do texto o contato que a redatora repetiu
const contatos = V.dados.contatos || [];
slides.forEach(s => {
  if (s.layout !== 'fechamento' || !s.texto || !contatos.length) return;
  let t = s.texto;
  contatos.forEach(c => { t = t.split(c).join(' '); });
  const sep = /(\s*[|·,;:\-–—]\s*)+$/, rotulo = /\s*(contatos?|fale (conosco|com a gente)|chame no|whatsapp|instagram|site)\s*:?\s*$/i;
  for (let k = 0; k < 4; k++) t = t.replace(sep, '').replace(rotulo, '');
  t = t.replace(/\s{2,}/g, ' ').trim();
  s.texto = t && !/[.!?]$/.test(t) ? t + '.' : t;
});
const capa = slides[0] || {};
const deck = {
  id: V.id, chave: V.chave, versao: 1, criado_em: V.criado_em, titulo: capa.titulo || P.titulo || V.dados.tema.slice(0, 70), autor: V.dados.autor, data_txt: V.data_txt,
  contatos: V.dados.contatos, link: V.apresentar, qr: `decks/${V.id}/qr.png`, tema: { nome: V.op.visual, cor }, t: apTokens(V.op.visual, cor), slides,
  op: { voz: V.op.voz, legendas: V.op.legendas, trilha: V.op.trilha, video: V.op.video }, publico: V.dados.publico, objetivo: V.dados.objetivo,
  revisao: { problemas: R.problemas, trocados: R.trocados, revisou: R.revisou, plano_simples: P.usou_reserva, trocas_plano: P.trocas, imagens: relato },
};
const html = apDocumento(deck, '__ARQ__');
return [{ json: { deck: JSON.stringify(deck), html, n: slides.length, cor: deck.t.cor, relato,
  corpo_pdf: JSON.stringify({ deck: V.id, html, slides: slides.length, qr: V.apresentar }), corpo_pptx: JSON.stringify({ deck: V.id, dados: deck }) } }];

// Links dos arquivos (PDF, PPTX, miniaturas e PNG de cada slide) da versão que acabou de ser gerada.
const pdf = $('🛠️ Oficina: PDF e imagens dos slides').first().json || {}, pptx = $('🛠️ Oficina: PowerPoint').first().json || {};
const deck = JSON.parse($('🧱 Monta a apresentação').first().json.deck);
const arq = { versao: deck.versao, quando: Date.now(), pdf: pdf.pdf || '', pdf_kb: pdf.pdf_kb || 0, paginas: pdf.paginas || 0, slides: pdf.slides || [], minis: pdf.minis || [],
  capa: pdf.capa || '', qr: pdf.qr || '', pptx: pptx.pptx || '', pptx_kb: pptx.pptx_kb || 0,
  erro: pdf.pdf ? (pptx.pptx ? '' : 'O PPTX não saiu desta vez (o PDF está pronto).') : String(pdf.detail || (pdf.error && pdf.error.message) || pdf.message || 'O PDF não saiu.').slice(0, 300) };
return [{ json: { arq: JSON.stringify(arq), ok: !!arq.pdf, ...arq } }];

// Resultado final: o que a página de andamento mostra (links, miniaturas, o que as revisoras ajustaram e o vídeo).
const tenta = f => { try { return f(); } catch (e) { return null; } };
const V = $('🧩 Confere o pedido').first().json, M = $('🧱 Monta a apresentação').first().json, A = $('🧩 Guarda os links dos arquivos').first().json;
const deck = JSON.parse(M.deck);
const pediuVideo = tenta(() => $('🌐 Pede o vídeo').first().json) || null;
