#grade .mi{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden;border-radius:10px;background:#1b1e25;box-shadow:0 0 0 1px #2b2f38}
#grade .mi .ap-s{position:absolute;left:0;top:0;transform-origin:0 0}
#grade .ativo .mi{box-shadow:0 0 0 3px var(--cor)}
#grade span{display:block;margin-top:6px;font:600 13px Inter,sans-serif;color:#b9c0cc}
#preto{position:fixed;inset:0;background:#000;z-index:6;cursor:pointer}
#aviso{position:fixed;left:50%;bottom:84px;transform:translateX(-50%);background:#1d2027;color:#fff;border:1px solid #2f343e;border-radius:12px;padding:10px 16px;font:600 14px Inter,sans-serif;z-index:7;opacity:0;transition:opacity .25s;pointer-events:none;max-width:calc(100vw - 32px);text-align:center}
#aviso.on{opacity:1}
#edbar{position:fixed;left:50%;top:12px;transform:translateX(-50%);background:#1d2027;border:1px solid #3a3f4a;border-radius:14px;padding:8px 10px 8px 16px;display:none;align-items:center;gap:10px;z-index:6;font:600 14px Inter,sans-serif;max-width:calc(100vw - 32px);flex-wrap:wrap}
body.editando #edbar{display:flex}body.editando #palco{top:72px}
#edbar button{background:#2b2f38;color:#fff;border:0;border-radius:10px;padding:10px 14px;font:700 14px Inter,sans-serif;cursor:pointer;min-height:40px}
#edbar #salvar{background:var(--cor);color:var(--corTinta)}#edbar #salvar:disabled{opacity:.45;cursor:default}
body.editando [data-c]{outline:2px dashed rgba(138,180,255,.75);outline-offset:6px;border-radius:6px;cursor:text}
body.editando [data-c]:focus{outline:3px solid #8ab4ff;background:rgba(138,180,255,.08)}
#lado{display:none}
body.apresentador #palco{left:16px;top:16px;right:38%;bottom:80px;border-radius:12px}
body.apresentador #lado{position:fixed;top:16px;right:16px;bottom:80px;width:calc(38% - 32px);display:flex;flex-direction:column;gap:12px}
#lado .prox{position:relative;width:100%;aspect-ratio:16/9;overflow:hidden;border-radius:10px;background:#1b1e25;box-shadow:0 0 0 1px #2b2f38;flex:none}
#lado .prox .ap-s{position:absolute;left:0;top:0;transform-origin:0 0}
#lado .rot{font:700 12px Inter,sans-serif;color:#98a1ae;text-transform:uppercase;letter-spacing:.06em}
#lado .tempo{display:flex;align-items:center;gap:14px;font:700 34px Inter,sans-serif;font-variant-numeric:tabular-nums}
#lado .tempo small{font-size:15px;color:#98a1ae;font-weight:600}
#lado .tempo button{background:#23262e;color:#fff;border:0;border-radius:10px;padding:8px 12px;font:600 13px Inter,sans-serif;cursor:pointer}
#lado .nota{flex:1;overflow:auto;font-size:21px;line-height:1.55;background:#15171c;border-radius:12px;padding:16px;color:#e8ebf0;white-space:pre-wrap}
body.apresentador #b-notas,body.apresentador #b-apres{display:none}
dialog{border:0;border-radius:14px;padding:0;background:#000;max-width:min(96vw,1280px);width:100%}
dialog::backdrop{background:rgba(0,0,0,.8)}
dialog video{width:100%;display:block}
dialog form{position:absolute;top:8px;right:8px}dialog form button{background:#0009;color:#fff;border:0;border-radius:10px;padding:8px 12px;font:700 14px Inter,sans-serif;cursor:pointer}
body.cheia #barra{opacity:0}body.cheia.mexeu #barra{opacity:1}body.cheia #progresso{bottom:0}body.cheia #palco{bottom:0}
@media (max-width:760px){#barra .tx,#barra #b-apres,#barra #b-tela{display:none}#barra{gap:2px;padding:0 6px}#barra button,#barra a{padding:0 8px;min-width:40px}#cont{min-width:50px}#notas{font-size:16px}}
@media (max-width:760px) and (orientation:portrait){body.com-notas #palco{bottom:auto;height:calc(56.25vw + 20px)}body.com-notas #progresso{bottom:auto;top:calc(56.25vw + 20px)}
body.com-notas #notas{top:calc(56.25vw + 23px);height:auto}}
@media (prefers-reduced-motion:reduce){#deck .ap-s{transition:none}}
</style></head>
<body class="${modo}${dono ? ' dono' : ''}">
