return [{ json: { codigo: 200, html, contar: !dono && !modo && !robo && q.p !== '1' } }];

// a criação responde na hora com o link do andamento; as IAs continuam em segundo plano
const r = $input.first().json;
if (!r.ok) throw new Error('A criação recusou o teste: ' + (r.erros || [r.message || 'sem resposta']).join(' '));
const chave = (String(r.link).match(/[?&]chave=([a-f0-9]+)/) || [])[1];   // o Code do n8n não tem a classe URL
