.L-capa .ap-veu{position:absolute;inset:0;background:linear-gradient(90deg,rgba(8,10,14,.88) 0%,rgba(8,10,14,.66) 46%,rgba(8,10,14,.12) 100%)}
.L-capa.com-img{--tinta:#FFFFFF;--tinta2:#E4E8EF;color:#fff}
.L-capa .ap-fit{right:auto;width:1200px;top:150px;bottom:170px;justify-content:flex-end}
.L-capa h1{font-size:2.85em;line-height:1.02}
.L-capa .ap-sub{font-size:1.12em;margin-top:.65em;color:var(--tinta2);line-height:1.35}
.L-capa .ap-autor{position:absolute;left:120px;bottom:70px;font-size:26px;color:var(--tinta2);font-weight:500}
.ap-deco1{position:absolute;right:-200px;top:-220px;width:920px;height:920px;border-radius:50%;background:var(--suave)}
.ap-deco2{position:absolute;right:260px;bottom:-280px;width:560px;height:560px;border-radius:50%;background:var(--cor);opacity:.16}
/* fundos fortes: vibrante usa a cor; corporativo usa a faixa escura */
.T-vibrante.L-capa.sem-img,.T-vibrante.L-secao,.T-vibrante.L-fechamento{background:var(--cor);--tinta:var(--corTinta);--tinta2:var(--corTinta);color:var(--corTinta)}
.T-vibrante.L-capa.sem-img .ap-marca,.T-vibrante.L-secao .ap-marca,.T-vibrante.L-fechamento .ap-marca{background:var(--corTinta)}
.T-vibrante.L-capa.sem-img .ap-deco1{background:var(--corTinta);opacity:.1}.T-vibrante.L-capa.sem-img .ap-deco2{background:var(--corTinta);opacity:.12}
.T-corporativo.L-capa.sem-img,.T-corporativo.L-secao{background:var(--faixa);--tinta:#FFFFFF;--tinta2:#C6D1E2;color:#fff}
.T-corporativo.L-capa.sem-img .ap-deco1{background:#FFFFFF;opacity:.06}
.T-corporativo:not(.L-capa):not(.L-secao):not(.L-fechamento)::before{content:'';position:absolute;left:0;right:0;top:0;height:14px;background:var(--faixa)}
/* seção */
.L-secao{background:var(--sup)}
.L-secao .ap-fit{justify-content:center}
.L-secao .ap-num{font-family:var(--ft),Montserrat,sans-serif;font-weight:var(--pesoT);font-size:5.4em;line-height:1;color:var(--cor);margin-bottom:.12em;letter-spacing:-.03em}
.T-vibrante.L-secao .ap-num,.T-corporativo.L-secao .ap-num{color:inherit;opacity:.88}
.L-secao h2{font-size:2.4em;max-width:1500px}
.L-secao .ap-txt{font-size:.95em;margin-top:.8em;max-width:1300px}
/* tópicos */
.ap-itens{display:grid;gap:1.1em 1.8em;flex:1;min-height:0;align-content:center}
.ap-itens.c2{grid-template-columns:1fr 1fr}
.ap-item{display:flex;gap:.75em;align-items:flex-start}
.ap-item h3{font-size:1.18em;margin:.2em 0 .2em}
.ap-item p{font-size:.94em;color:var(--tinta2);line-height:1.4}
/* imagem + texto */
.L-imagem_texto .ap-img{position:absolute;top:0;bottom:0;right:0;width:50%;height:100%;object-fit:cover}
.L-imagem_texto.esq .ap-img{left:0;right:auto}
.L-imagem_texto.com-img .ap-fit{right:calc(50% + 100px)}
.L-imagem_texto.com-img.esq .ap-fit{left:calc(50% + 100px);right:120px}
.L-imagem_texto.com-img .ap-rod{right:calc(50% + 100px)}
.L-imagem_texto.com-img.esq .ap-rod{left:calc(50% + 100px);right:120px}
.L-imagem_texto .ap-fit{justify-content:center}.L-imagem_texto .ap-h2{margin-bottom:.6em}.L-imagem_texto .ap-corpo{flex:none;display:flex;flex-direction:column}
.L-imagem_texto .ap-txt{font-size:1.08em}
.L-imagem_texto .ap-itens{grid-template-columns:1fr;align-content:center}
/* colunas */
.ap-cols{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:1.1em;flex:1;min-height:0;align-content:center}
.ap-card{background:var(--sup);border-radius:.8em;padding:1.45em 1.35em;display:flex;flex-direction:column;gap:.7em;min-width:0}.ap-card .ap-ico{width:2.7em;height:2.7em}
.ap-card h3{font-size:1.25em;margin-top:.3em}
.ap-card p{font-size:.95em;color:var(--tinta2);line-height:1.42}
/* números */
.ap-nums{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:1.1em;flex:1;min-height:0;align-content:center}
.ap-numc{background:var(--sup);border-radius:.8em;padding:1.6em 1.35em;min-height:8.6em;display:flex;flex-direction:column;justify-content:center;min-width:0}
.ap-numc .v{font-family:var(--ft),Montserrat,sans-serif;font-weight:var(--pesoT);line-height:1;color:var(--cor);letter-spacing:-.02em;white-space:nowrap}
.ap-numc .r{font-size:1.05em;font-weight:700;margin-top:.6em;line-height:1.25}
.ap-numc .d{font-size:.86em;color:var(--tinta2);margin-top:.4em;line-height:1.4}
/* gráfico */
.ap-gw{display:flex;gap:1.5em;flex:1;min-height:0}
.ap-g{flex:0 0 63%;min-width:0;min-height:0;display:flex;flex-direction:column}
.ap-g .gt{font-size:.7em;font-weight:600;color:var(--tinta2);margin-bottom:.5em}
.ap-g svg{flex:1;width:100%;min-height:0}
.ap-ins{flex:1;display:flex;flex-direction:column;justify-content:center;gap:.7em;min-width:0;border-left:.12em solid var(--linha);padding-left:1.2em}
.ap-ins .big{font-family:var(--ft),Montserrat,sans-serif;font-weight:var(--pesoT);font-size:1.25em;line-height:1.22}
.ap-ins .fonte{font-size:.6em;color:var(--tinta2)}
/* etapas */
.ap-etapas{display:grid;grid-auto-flow:column;grid-auto-columns:1fr;gap:1em;flex:1;min-height:0;align-content:center}
.ap-etapa{display:flex;flex-direction:column;align-items:center;text-align:center;position:relative;min-width:0}
.ap-etapa .n{width:3em;height:3em;font-size:1em;border-radius:50%;background:var(--cor);color:var(--corTinta);font-family:var(--ft),Montserrat,sans-serif;font-weight:var(--pesoT);
display:flex;align-items:center;justify-content:center;position:relative;z-index:1;flex:none}
.ap-etapa:not(:first-child)::before{content:'';position:absolute;top:1.42em;left:calc(-50% - 1em);right:50%;height:.16em;background:var(--linha)}
.ap-etapa h3{font-size:1.18em;margin:.75em 0 .3em}
.ap-etapa p{font-size:.9em;color:var(--tinta2);line-height:1.42}
/* comparação */
.ap-comp{display:grid;grid-template-columns:1fr 1fr;gap:1.2em;flex:1;min-height:0;align-content:center}
.ap-lado{background:var(--sup);border-radius:.8em;padding:1.45em 1.5em;display:flex;flex-direction:column;gap:.7em;min-width:0}
.ap-lado.b{background:var(--suave);box-shadow:inset 0 0 0 .09em var(--cor)}
.ap-lado h3{font-size:1.28em;margin-bottom:.3em}
.ap-lado li{display:flex;gap:.6em;font-size:.98em;line-height:1.38}
.ap-lado li i{font-style:normal;font-weight:800;color:var(--tinta2);flex:none}
.ap-lado.b li i{color:var(--cor)}
/* citação */
.L-citacao{background:var(--sup)}
.L-citacao .ap-fit{justify-content:center;left:220px;right:220px}
.L-citacao .aspas{font-family:var(--ft),Montserrat,sans-serif;font-weight:800;font-size:6em;line-height:.62;color:var(--cor);height:.42em}
.L-citacao blockquote{font-family:var(--ft),Montserrat,sans-serif;font-size:1.55em;line-height:1.3;font-weight:600}
.T-elegante.L-citacao blockquote{font-style:italic;font-weight:500}
.L-citacao .autor{margin-top:1em;font-size:.88em;color:var(--tinta2);font-weight:700}
.L-citacao .ap-fundo{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;opacity:.16}
/* fechamento */
.L-fechamento .ap-fit{justify-content:center}
.L-fechamento.com-qr .ap-fit{right:680px}
.L-fechamento h2{font-size:2.6em;line-height:1.04}
.L-fechamento .ap-txt{font-size:1em;margin-top:.7em}
.L-fechamento .ap-cont{margin-top:1.1em;display:flex;flex-direction:column;gap:.3em;font-size:.86em;font-weight:600}
.L-fechamento .ap-qr{position:absolute;right:140px;top:50%;transform:translateY(-50%);width:440px;text-align:center}
.L-fechamento .ap-qr img{width:440px;height:440px;background:#fff;border-radius:28px;padding:26px;display:block;box-shadow:0 0 0 2px var(--linha)}
.L-fechamento .ap-qr p{margin-top:18px;font-size:25px;color:var(--tinta2);font-weight:500}`;
}

// ───── gráfico em SVG (uma série só, uma cor, eixo discreto, rótulo nos valores) ─────
function apNum(v, g, compacto) {
  const casas = (g.valores || []).some(x => Math.round(Number(x)) !== Number(x)) ? 1 : 0;
  const n = Number(v);
  const txt = compacto && Math.abs(n) >= 100000 ? new Intl.NumberFormat('pt-BR', { notation: 'compact', maximumFractionDigits: 1 }).format(n)
    : n.toLocaleString('pt-BR', { minimumFractionDigits: casas, maximumFractionDigits: casas });
  return (g.prefixo || '') + txt + (g.sufixo || '');
}
function apEscala(min, max) {
  const span = (max - min) || Math.abs(max) || 1, p0 = span / 4, mag = Math.pow(10, Math.floor(Math.log10(p0))), r = p0 / mag;
  const passo = (r <= 1 ? 1 : r <= 2 ? 2 : r <= 2.5 ? 2.5 : r <= 5 ? 5 : 10) * mag;
  return { min: Math.floor(min / passo) * passo, max: Math.ceil(max / passo) * passo, passo };
}
function apGrafico(g, t) {
  const n = Math.min((g.rotulos || []).length, (g.valores || []).length);
  const rot = (g.rotulos || []).slice(0, n).map(String), val = (g.valores || []).slice(0, n).map(Number);
  if (n < 2) return '';
  let tipo = ['barras', 'barras_h', 'linha'].includes(g.tipo) ? g.tipo : 'barras';
  if (tipo === 'barras' && (n > 8 || rot.some(r => r.length > 12))) tipo = 'barras_h';
  const W = 1100, H = 640, f = (x, k = 1) => Number(x).toFixed(k);
  const txt = (x, y, s, o = '') => `<text x="${f(x)}" y="${f(y)}" ${o}>${apEsc(s)}</text>`;
  const aria = `role="img" aria-label="${apEsc((g.titulo || 'Gráfico') + ': ' + rot.map((r, i) => r + ' ' + apNum(val[i], g)).join('; '))}"`;
  let o = `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" ${aria} font-family="${apEsc(t.fc)}, Inter, sans-serif">`;
  if (tipo === 'barras_h') {
    const L = Math.min(380, 30 + Math.max(...rot.map(r => r.length)) * 15), R = 170, T = 10, B = 10;
    const lo = Math.min(0, ...val), hi = Math.max(0, ...val), esc = v => L + (v - lo) / ((hi - lo) || 1) * (W - L - R);
    const banda = (H - T - B) / n, bh = Math.min(64, banda * 0.62);
    rot.forEach((r, i) => {
      const y = T + banda * i + (banda - bh) / 2, x0 = esc(0), x1 = esc(val[i]), a = Math.min(x0, x1), w = Math.max(2, Math.abs(x1 - x0)), rr = Math.min(10, w / 2, bh / 2);
      const pos = val[i] >= 0;
      o += `<path d="${pos ? `M${f(a)},${f(y)} h${f(w - rr)} a${rr},${rr} 0 0 1 ${rr},${rr} v${f(bh - 2 * rr)} a${rr},${rr} 0 0 1 -${rr},${rr} h-${f(w - rr)} z`
        : `M${f(a + w)},${f(y)} h-${f(w - rr)} a${rr},${rr} 0 0 0 -${rr},${rr} v${f(bh - 2 * rr)} a${rr},${rr} 0 0 0 ${rr},${rr} h${f(w - rr)} z`}" fill="${t.cor}"><title>${apEsc(r + ': ' + apNum(val[i], g))}</title></path>`;
      o += txt(L - 18, y + bh / 2 + 9, r.length > 26 ? r.slice(0, 25) + '…' : r, `text-anchor="end" font-size="26" fill="${t.tinta}"`);
      o += txt(pos ? x1 + 14 : x1 - 14, y + bh / 2 + 10, apNum(val[i], g), `text-anchor="${pos ? 'start' : 'end'}" font-size="28" font-weight="700" fill="${t.tinta}"`);
    });
    o += `<line x1="${f(esc(0))}" x2="${f(esc(0))}" y1="${T}" y2="${H - B}" stroke="${t.tinta2}" stroke-width="2"/>`;
    return o + '</svg>';
  }
  const L = 96, R = 24, T = 52, B = 64;
  const e = apEscala(Math.min(0, ...val), Math.max(0, ...val));
  const y = v => T + (e.max - v) / ((e.max - e.min) || 1) * (H - T - B);
  for (let v = e.min; v <= e.max + e.passo / 2; v += e.passo) {
    o += `<line x1="${L}" x2="${W - R}" y1="${f(y(v))}" y2="${f(y(v))}" stroke="${Math.abs(v) < e.passo / 1e6 ? t.tinta2 : t.linha}" stroke-width="2"/>`;
    o += txt(L - 14, y(v) + 8, apNum(v, { valores: g.valores }, true), `text-anchor="end" font-size="22" fill="${t.tinta2}"`);
  }
  const banda = (W - L - R) / n, cx = i => L + banda * i + banda / 2, pula = Math.ceil(n / 8);
  rot.forEach((r, i) => { if (i % pula === 0 || i === n - 1) o += txt(cx(i), H - B + 40, r.length > 14 ? r.slice(0, 13) + '…' : r, `text-anchor="middle" font-size="25" fill="${t.tinta2}"`); });
  if (tipo === 'linha') {
    const pts = val.map((v, i) => [cx(i), y(v)]);
    o += `<path d="M${pts.map(p => f(p[0]) + ',' + f(p[1])).join(' L')} L${f(pts[n - 1][0])},${f(y(Math.max(e.min, 0)))} L${f(pts[0][0])},${f(y(Math.max(e.min, 0)))} z" fill="${t.cor}" opacity=".10"/>`;
    o += `<path d="M${pts.map(p => f(p[0]) + ',' + f(p[1])).join(' L')}" fill="none" stroke="${t.cor}" stroke-width="6" stroke-linejoin="round" stroke-linecap="round"/>`;
    const imax = val.indexOf(Math.max(...val)), imin = val.indexOf(Math.min(...val));
    pts.forEach((p, i) => {
      o += `<circle cx="${f(p[0])}" cy="${f(p[1])}" r="10" fill="${t.cor}" stroke="${t.bg}" stroke-width="4"><title>${apEsc(rot[i] + ': ' + apNum(val[i], g))}</title></circle>`;
      if (i === 0 || i === n - 1 || i === imax || i === imin) o += txt(p[0], p[1] - 22, apNum(val[i], g), `text-anchor="middle" font-size="28" font-weight="700" fill="${t.tinta}"`);
    });
  } else {
    const bw = Math.min(120, banda * 0.62);
    val.forEach((v, i) => {
      const x = cx(i) - bw / 2, y0 = y(0), y1 = y(v), h = Math.max(2, Math.abs(y1 - y0)), rr = Math.min(10, bw / 2, h / 2), pos = v >= 0;
      o += `<path d="${pos ? `M${f(x)},${f(y0)} v-${f(h - rr)} a${rr},${rr} 0 0 1 ${rr},-${rr} h${f(bw - 2 * rr)} a${rr},${rr} 0 0 1 ${rr},${rr} v${f(h - rr)} z`
        : `M${f(x)},${f(y0)} v${f(h - rr)} a${rr},${rr} 0 0 0 ${rr},${rr} h${f(bw - 2 * rr)} a${rr},${rr} 0 0 0 ${rr},-${rr} v-${f(h - rr)} z`}" fill="${t.cor}"><title>${apEsc(rot[i] + ': ' + apNum(v, g))}</title></path>`;
      o += txt(cx(i), pos ? y1 - 16 : y1 + 36, apNum(v, g), `text-anchor="middle" font-size="28" font-weight="700" fill="${t.tinta}"`);
    });
  }
  return o + '</svg>';
}

// ───── um slide ─────  (data-c = campo editável pelo dono: "<slide>.<campo>")
function apSlide(d, s, i, base) {
  const t = d.t, total = d.slides.length, lay = AP_LAYOUTS.includes(s.layout) ? s.layout : 'topicos';
  const E = (campo, tag, cls, valor) => `<${tag}${cls ? ` class="${cls}"` : ''} data-c="${i}.${campo}">${apEsc(valor)}</${tag}>`;
  const img = s.imagem && s.imagem.arquivo ? `${base}/${s.imagem.arquivo}` : '';
  const foco = s.imagem && s.imagem.foco ? `${Math.round((+s.imagem.foco.x || 0.5) * 100)}% ${Math.round((+s.imagem.foco.y || 0.5) * 100)}%` : '50% 50%';
  const alt = s.imagem && s.imagem.alt ? apEsc(s.imagem.alt) : '';
  const titulo = (cls = 'ap-h2') => `<div class="ap-marca"></div>${E('titulo', 'h2', cls, s.titulo)}`;
  const itens = (lst, icones = true) => (lst || []).map((it, k) => `<li class="ap-item">${icones ? `<div class="ap-ico"><span>${apEsc(it.icone || '•')}</span></div>` : ''}<div>${E(`itens.${k}.t`, 'h3', '', it.t)}${it.d ? E(`itens.${k}.d`, 'p', '', it.d) : ''}</div></li>`).join('');
  const rod = `<div class="ap-rod"><span>${apEsc(d.titulo)}</span><span>${i + 1} / ${total}</span></div>`;
  let cls = '', corpo = '', comRod = true;
  if (lay === 'capa') {
    comRod = false;
    corpo = (img ? `<img class="ap-fundo" src="${img}" alt="${alt}" style="object-position:${foco}"><div class="ap-veu"></div>` : '<div class="ap-deco1"></div><div class="ap-deco2"></div>')
      + `<div class="ap-fit"><div class="ap-marca"></div>${E('titulo', 'h1', '', s.titulo)}${s.subtitulo ? E('subtitulo', 'p', 'ap-sub', s.subtitulo) : ''}</div>`
      + `<p class="ap-autor">${apEsc([d.autor, d.data_txt].filter(Boolean).join(' · '))}</p>`;
  } else if (lay === 'secao') {
    comRod = false;
    const num = d.slides.slice(0, i + 1).filter(x => x.layout === 'secao').length;
    corpo = `<div class="ap-fit"><div class="ap-num">${String(num).padStart(2, '0')}</div>${E('titulo', 'h2', '', s.titulo)}${s.texto ? E('texto', 'p', 'ap-txt', s.texto) : ''}</div>`;
  } else if (lay === 'imagem_texto') {
    cls = i % 2 ? '' : 'esq';
    corpo = (img ? `<img class="ap-img" src="${img}" alt="${alt}" style="object-position:${foco}">` : '')
      + `<div class="ap-fit">${titulo()}<div class="ap-corpo ap-cresce">${(s.itens || []).length ? `<ul class="ap-itens">${itens(s.itens)}</ul>` : E('texto', 'p', 'ap-txt', s.texto)}</div></div>`;
  } else if (lay === 'colunas') {
    corpo = `<div class="ap-fit">${titulo()}<div class="ap-cols ap-cresce">${(s.itens || []).map((it, k) => `<div class="ap-card"><div class="ap-ico"><span>${apEsc(it.icone || '•')}</span></div>${E(`itens.${k}.t`, 'h3', '', it.t)}${E(`itens.${k}.d`, 'p', '', it.d)}</div>`).join('')}</div></div>`;
  } else if (lay === 'numeros') {
    const ns = s.numeros || [], larg = (1680 - 40 * (ns.length - 1)) / Math.max(1, ns.length) / 36 - 2.5;
    corpo = `<div class="ap-fit">${titulo()}<div class="ap-nums">${ns.map((x, k) => {
      const fs = Math.max(1.4, Math.min(3.1, larg / (Math.max(3, String(x.v || '').length) * 0.6)));
      return `<div class="ap-numc"><div class="v" style="font-size:${fs.toFixed(2)}em" data-c="${i}.numeros.${k}.v">${apEsc(x.v)}</div>${E(`numeros.${k}.r`, 'div', 'r', x.r)}${x.d ? E(`numeros.${k}.d`, 'div', 'd', x.d) : ''}</div>`;
    }).join('')}</div></div>`;
  } else if (lay === 'grafico') {
    const g = s.grafico || {};
    corpo = `<div class="ap-fit">${titulo()}<div class="ap-gw"><div class="ap-g">${g.titulo ? `<div class="gt">${apEsc(g.titulo)}</div>` : ''}${apGrafico(g, t)}</div>`
      + `<div class="ap-ins">${s.destaque ? E('destaque', 'p', 'big', s.destaque) : ''}${g.fonte ? `<p class="fonte">Fonte: ${apEsc(g.fonte)}</p>` : ''}</div></div></div>`;
  } else if (lay === 'etapas') {
    corpo = `<div class="ap-fit">${titulo()}<div class="ap-etapas ap-cresce">${(s.itens || []).map((it, k) => `<div class="ap-etapa"><div class="n">${k + 1}</div>${E(`itens.${k}.t`, 'h3', '', it.t)}${it.d ? E(`itens.${k}.d`, 'p', '', it.d) : ''}</div>`).join('')}</div></div>`;
  } else if (lay === 'comparacao') {
    const c = s.comparacao || {};
    const lado = (k, marca) => `<div class="ap-lado ${k}">${E(`comparacao.${k}.titulo`, 'h3', '', (c[k] || {}).titulo)}<ul>${((c[k] || {}).itens || []).map((x, j) => `<li><i>${marca}</i>${E(`comparacao.${k}.itens.${j}`, 'span', '', x)}</li>`).join('')}</ul></div>`;
    corpo = `<div class="ap-fit">${titulo()}<div class="ap-comp ap-cresce">${lado('a', '•')}${lado('b', '✓')}</div></div>`;
  } else if (lay === 'citacao') {
    comRod = false;
    const c = s.citacao || {};
    corpo = (img ? `<img class="ap-fundo" src="${img}" alt="" style="object-position:${foco}">` : '')
      + `<div class="ap-fit"><div class="aspas">“</div>${E('citacao.texto', 'blockquote', '', c.texto)}${c.autor ? `<p class="autor">— <span data-c="${i}.citacao.autor">${apEsc(c.autor)}</span></p>` : ''}</div>`;
  } else if (lay === 'fechamento') {
    comRod = false;
    const qr = d.qr ? `${base}/${d.qr}` : '';
    cls = qr ? 'com-qr' : '';
    corpo = `<div class="ap-fit"><div class="ap-marca"></div>${E('titulo', 'h2', '', s.titulo)}${s.texto ? E('texto', 'p', 'ap-txt', s.texto) : ''}`
      + `${(d.contatos || []).length ? `<div class="ap-cont">${d.contatos.map(x => `<span>${apEsc(x)}</span>`).join('')}</div>` : ''}</div>`
      + (qr ? `<div class="ap-qr"><img src="${qr}" alt="QR code para abrir esta apresentação"><p>Aponte a câmera para baixar a apresentação</p></div>` : '');
  } else {   // tópicos
    const lst = s.itens || [];
    corpo = `<div class="ap-fit">${titulo()}${lst.length ? `<ul class="ap-itens ap-cresce${lst.length >= 4 ? ' c2' : ''}">${itens(lst)}</ul>` : E('texto', 'p', 'ap-txt ap-cresce', s.texto)}</div>`;
  }
  return `<section class="ap-s L-${lay} T-${t.nome} ${img ? 'com-img' : 'sem-img'} ${cls}" data-i="${i}" aria-label="Slide ${i + 1} de ${total}">${corpo}${comRod ? rod : ''}</section>`;
}

// diminui a letra do bloco de texto que não coube (roda na página e no Chromium que faz o PDF)
// o corpo (.ap-cresce) começa 22% maior e desce até caber; sem corpo marcado, o bloco todo só diminui
const AP_AJUSTA = `function apAjusta(raiz){(raiz||document).querySelectorAll('.ap-fit').forEach(function(el){
var alvo=el.querySelector('.ap-cresce')||el,b=parseFloat(alvo.getAttribute('data-base')||'');if(!b){b=parseFloat(getComputedStyle(alvo).fontSize)||36;alvo.setAttribute('data-base',b);}
var f=alvo===el?1:1.22;alvo.style.fontSize=(b*f)+'px';while(f>0.6&&(el.scrollHeight>el.clientHeight+2||el.scrollWidth>el.clientWidth+2)){f-=0.04;alvo.style.fontSize=(b*f)+'px';}});}`;

// documento para o PDF: um slide por página de 1920×1080
function apDocumento(d, base) {
  return `<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><title>${apEsc(d.titulo)}</title><style>${apCSS(d.t)}
@page{size:1920px 1080px;margin:0}html,body{margin:0;padding:0;background:${d.t.bg}}.ap-s{break-after:page;page-break-after:always}.ap-s:last-child{break-after:auto;page-break-after:auto}</style></head>
<body>${d.slides.map((s, i) => apSlide(d, s, i, base)).join('')}<script>${AP_AJUSTA}
(document.fonts&&document.fonts.ready?document.fonts.ready:Promise.resolve()).then(function(){apAjusta(document);document.body.setAttribute('data-pronto','1');});</script></body></html>`;
}

// Confere o plano da planejadora: capa no começo, fechamento no fim, layouts válidos, quantidade pedida
// e gráfico/números só se o usuário deu números. Se a planejadora falhar, usa um plano simples.
const V = $('🧩 Confere o pedido').first().json;
let p = null;
try { p = parseJSON($('🤖 Planejadora da apresentação').first().json.output); } catch (e) {}
p = p || {};
const N = V.op.slides;
let sl = (Array.isArray(p.slides) ? p.slides : []).filter(s => s && AP_LAYOUTS.includes(s.layout))
  .map(s => ({ layout: s.layout, titulo: String(s.titulo || '').slice(0, 90), objetivo: String(s.objetivo || '').slice(0, 200),
    pontos: (Array.isArray(s.pontos) ? s.pontos : []).map(x => String(x).slice(0, 160)).slice(0, 6), imagem: s.imagem === true, dados: String(s.dados || '').slice(0, 300) }));
const usou_reserva = sl.length < 4;
if (usou_reserva) {   // plano simples: ainda dá uma apresentação inteira
  const meio = ['topicos', 'imagem_texto', 'colunas', 'etapas', 'comparacao', 'topicos', 'colunas', 'imagem_texto', 'etapas', 'topicos', 'colunas', 'topicos', 'imagem_texto'];
  sl = [{ layout: 'capa', titulo: '', pontos: [], imagem: true }].concat(meio.slice(0, N - 2).map(l => ({ layout: l, titulo: '', pontos: [], imagem: l === 'imagem_texto' })),
    [{ layout: 'fechamento', titulo: '', pontos: [], imagem: false }]);
}
sl = sl.filter((s, i) => !((s.layout === 'capa' && i > 0) || (s.layout === 'fechamento' && i < sl.length - 1)));
if (!sl.length || sl[0].layout !== 'capa') sl.unshift({ layout: 'capa', titulo: '', pontos: [], imagem: true });
if (sl[sl.length - 1].layout !== 'fechamento') sl.push({ layout: 'fechamento', titulo: '', pontos: [], imagem: false });
while (sl.length > Math.min(15, N + 1)) sl.splice(sl.length - 2, 1);   // corta do meio, nunca a capa nem o fechamento
const trocas = [];
if (!V.numeros_usuario.length) sl.forEach((s, i) => { if (s.layout === 'grafico' || s.layout === 'numeros') { trocas.push(`slide ${i + 1}: ${s.layout} virou tópicos (você não deu números)`); s.layout = 'topicos'; } });
const fotos = V.op.imagens ? ['capa', 'imagem_texto', 'citacao'] : [];
sl.forEach(s => { s.imagem = fotos.includes(s.layout) && (s.layout !== 'citacao' ? true : s.imagem); });
let comImagem = 0;   // no máximo 7 imagens (cada uma leva ~20 s)
sl.forEach(s => { if (s.imagem && ++comImagem > 7) s.imagem = false; });
sl.forEach((s, i) => { s.n = i + 1; });
const plano = sl.map(s => `${s.n}. ${s.layout}${s.imagem ? ' (com imagem)' : ''} — título sugerido: ${s.titulo || '(você escolhe)'}${s.objetivo ? ' — objetivo: ' + s.objetivo : ''}${s.pontos.length ? ' — pontos: ' + s.pontos.join('; ') : ''}${s.dados ? ' — dados: ' + s.dados : ''}`).join('\n');
return [{ json: {
  plano: sl, titulo: String(p.titulo || '').slice(0, 90), mensagem: String(p.mensagem_central || '').slice(0, 240), estilo: String(p.estilo_imagens || '').slice(0, 200),
  cor: /^#[0-9a-fA-F]{6}$/.test(p.cor || '') ? String(p.cor).toUpperCase() : '', usou_reserva, trocas,
  texto_redatora: `DADOS DO USUÁRIO:\n${V.resumo_ia}\n\nMENSAGEM CENTRAL: ${String(p.mensagem_central || '(defina pelo assunto)')}\n\nPLANO APROVADO (siga a ordem e o layout de cada slide; ${sl.length} slides):\n${plano}`,
} }];

function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Desenho dos slides: o MESMO na página de apresentar, no PDF, nas miniaturas e no vídeo (tela de 1920×1080).
const AP_TEMAS = {
  claro: { nome: 'claro', bg: '#FFFFFF', sup: '#F3F5F8', tinta: '#12151B', tinta2: '#4B5361', linha: '#E2E6EC', ft: 'Montserrat', fc: 'Inter', pesoT: 800, cor: '#2563EB' },
  escuro: { nome: 'escuro', bg: '#0E1117', sup: '#1A1E27', tinta: '#F4F6F9', tinta2: '#A9B2C0', linha: '#2C323D', ft: 'Montserrat', fc: 'Inter', pesoT: 800, cor: '#38BDF8' },
  elegante: { nome: 'elegante', bg: '#FAF7F2', sup: '#F1EADF', tinta: '#1E1A15', tinta2: '#5F574C', linha: '#E3D9C9', ft: 'Playfair Display', fc: 'Inter', pesoT: 700, cor: '#8C5A2B' },
  vibrante: { nome: 'vibrante', bg: '#FFFFFF', sup: '#F6F2FB', tinta: '#16121F', tinta2: '#4E4A57', linha: '#E9E3F1', ft: 'Montserrat', fc: 'Inter', pesoT: 800, cor: '#D6246E' },
  corporativo: { nome: 'corporativo', bg: '#FFFFFF', sup: '#F2F5F9', tinta: '#0B1B33', tinta2: '#46566B', linha: '#DCE3EC', ft: 'Montserrat', fc: 'Inter', pesoT: 700, cor: '#1F5FD1', faixa: '#0B2545' },
};
const AP_LAYOUTS = ['capa', 'secao', 'topicos', 'imagem_texto', 'colunas', 'numeros', 'grafico', 'etapas', 'comparacao', 'citacao', 'fechamento'];
const apHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const apLum = h => apHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const apContraste = (a, b) => { const x = apLum(a), y = apLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const apMistura = (a, b, k) => { const x = apHex(a), y = apHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
// cores do tema + a cor de destaque ajustada para aparecer no fundo (>= 3:1, como texto grande e gráfico)
function apTokens(nome, cor) {
  const t = Object.assign({}, AP_TEMAS[nome] || AP_TEMAS.claro);
  let c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : t.cor;
  const escuro = apLum(t.bg) < 0.2;
  for (let i = 0; i < 14 && apContraste(c, t.bg) < 3; i++) c = apMistura(c, escuro ? '#FFFFFF' : '#000000', 0.12);
  t.cor = c;
  t.corTinta = apContraste('#FFFFFF', c) >= 4.5 ? '#FFFFFF' : '#111111';   // texto em cima da cor
  t.suave = apMistura(c, t.bg, escuro ? 0.8 : 0.87);                        // fundo dos ícones e do lado "depois"
  return t;
}
const apEsc = v => String(v ?? '').replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));

