  if (lay === 'capa') {
    comRod = false;
    corpo = (img ? `<img class="ap-fundo" src="${img}" alt="${alt}" style="object-position:${foco}"><div class="ap-veu"></div>` : '<div class="ap-deco1"></div><div class="ap-deco2"></div>')
      + `<div class="ap-fit"><div class="ap-marca"></div>${E('titulo', 'h1', '', s.titulo)}${s.subtitulo ? E('subtitulo', 'p', 'ap-sub', s.subtitulo) : ''}</div>`
