// Confere os slides da redatora: um por item do plano, no layout do plano, com os tamanhos e as listas certas.
// Também separa os números que não estão nos dados do usuário (a revisora corrige; o que sobrar sai no fim).
const V = $('🧩 Confere o pedido').first().json, P = $('🧩 Lê o plano').first().json;
let r = null;
try { r = parseJSON($('🤖 Redatora dos slides').first().json.output); } catch (e) {}
const lst = r && Array.isArray(r.slides) ? r.slides : [];
const ultimo = P.plano.length - 1;
const slides = P.plano.map((pl, i) => {
  const s = lst.find(x => Number(x && x.n) === pl.n) || lst[i] || {};
  // se a redatora trocou o layout no meio, vale o dela (o conteúdo foi escrito para ele); capa e fechamento ficam
  const lay = i > 0 && i < ultimo && AP_LAYOUTS.includes(s.layout) && !['capa', 'fechamento'].includes(s.layout) ? s.layout : pl.layout;
