function parseJSON(txt) {
  const s = String(txt || '').replace(/^\s*```(?:json)?\s*/i, '').replace(/```\s*$/i, '').trim();
  try { return JSON.parse(s); } catch (e) {}
  const a = s.indexOf('{'), b = s.lastIndexOf('}');
  if (a > -1 && b > a) { try { return JSON.parse(s.slice(a, b + 1)); } catch (e) {} }
  return null;
}

// Regras do conteúdo dos slides (iguais na redatora, na revisora e na edição do dono).
const apT = (v, max) => String(v ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
const apEmoji = (v, k) => { const m = String(v || '').match(/\p{Extended_Pictographic}(️|‍\p{Extended_Pictographic})*/u); return m ? m[0] : ['💡', '✅', '🎯', '🚀', '📌'][k % 5]; };
// todos os números de um texto ("R$ 48 mil" = 48 e 48000; "1.240" = 1240; "4,5" = 4.5)
function apNumeros(t) {
  const out = [], s0 = String(t || ''), re = /\d[\d.,]*/g;
  let m;
  while ((m = re.exec(s0))) {
    const s = m[0].replace(/[.,]+$/, ''), depois = s0.slice(m.index + m[0].length, m.index + m[0].length + 12).toLowerCase();
    const mult = /^\s*(mil\b|k\b)/.test(depois) ? 1e3 : /^\s*(milh|mi\b)/.test(depois) ? 1e6 : /^\s*(bilh|bi\b)/.test(depois) ? 1e9 : 1;
