}
// o que não dá para mostrar no layout pedido vira tópicos (lista vazia, gráfico sem números, comparação com um lado só)
function apEstrutura(o) {
  const vira = (itens, texto) => Object.assign({ n: o.n, layout: 'topicos', titulo: o.titulo, notas: o.notas, narracao: o.narracao }, itens.length >= 2 ? { itens } : { itens: [], texto: apT(texto || o.notas, 400) });
  if (o.layout === 'grafico' && !(o.grafico.valores.length >= 2 && o.grafico.valores.every(v => isFinite(v)))) return vira([], o.destaque);
  if (o.layout === 'numeros' && o.numeros.length < 2) return vira(o.numeros.map((x, k) => ({ icone: apEmoji('', k), t: x.v + ' ' + x.r, d: x.d })), '');
  if ((o.layout === 'colunas' || o.layout === 'etapas') && o.itens.length < 2) return vira(o.itens.map((x, k) => ({ icone: apEmoji(x.icone, k), t: x.t, d: x.d })), '');
  if (o.layout === 'comparacao' && !(o.comparacao.a.itens.length && o.comparacao.b.itens.length)) {
    const it = o.comparacao.a.itens.concat(o.comparacao.b.itens).map((t, k) => ({ icone: apEmoji('', k), t, d: '' }));
    return vira(it, '');
  }
  if (o.layout === 'citacao' && !o.citacao.texto) return vira([], o.notas);
  if (o.layout === 'fechamento' && !o.titulo) o.titulo = 'Obrigado!';
  return o;
}
// números do slide que não estão nos dados do usuário (gráfico e "números")
function apNumerosFora(o, lista) {
