const capa = slides[0] || {};
const deck = {
  id: V.id, chave: V.chave, versao: 1, criado_em: V.criado_em, titulo: capa.titulo || P.titulo || V.dados.tema.slice(0, 70), autor: V.dados.autor, data_txt: V.data_txt,
  contatos: V.dados.contatos, link: V.apresentar, qr: `decks/${V.id}/qr.png`, tema: { nome: V.op.visual, cor }, t: apTokens(V.op.visual, cor), slides,
  op: { voz: V.op.voz, legendas: V.op.legendas, trilha: V.op.trilha, video: V.op.video }, publico: V.dados.publico, objetivo: V.dados.objetivo,
  revisao: { problemas: R.problemas, trocados: R.trocados, revisou: R.revisou, plano_simples: P.usou_reserva, trocas_plano: P.trocas, imagens: relato },
};
const html = apDocumento(deck, '__ARQ__');
return [{ json: { deck: JSON.stringify(deck), html, n: slides.length, cor: deck.t.cor, relato,
  corpo_pdf: JSON.stringify({ deck: V.id, html, slides: slides.length, qr: V.apresentar }), corpo_pptx: JSON.stringify({ deck: V.id, dados: deck }) } }];

// Links dos arquivos (PDF, PPTX, miniaturas e PNG de cada slide) da versão que acabou de ser gerada.
const pdf = $('🛠️ Oficina: PDF e imagens dos slides').first().json || {}, pptx = $('🛠️ Oficina: PowerPoint').first().json || {};
const deck = JSON.parse($('🧱 Monta a apresentação').first().json.deck);
const arq = { versao: deck.versao, quando: Date.now(), pdf: pdf.pdf || '', pdf_kb: pdf.pdf_kb || 0, paginas: pdf.paginas || 0, slides: pdf.slides || [], minis: pdf.minis || [],
  capa: pdf.capa || '', qr: pdf.qr || '', pptx: pptx.pptx || '', pptx_kb: pptx.pptx_kb || 0,
