// Pedido do vídeo narrado: confere a chave e se o PDF desta versão já existe (o vídeo usa a imagem de cada slide);
// a fala de cada slide é a "narração" escrita pela IA (ou o próprio texto do slide).
const b = $('🧩 Lê o pedido do vídeo').first().json;
let deck = null, arq = null, vid = null;
try { deck = JSON.parse($('📖 Lê a apresentação (vídeo)').first().json.deck || 'null'); } catch (e) {}
try { arq = JSON.parse($('📖 Lê os arquivos (vídeo)').first().json.arq || 'null'); } catch (e) {}
try { vid = JSON.parse($('📖 Lê o vídeo (vídeo)').first().json.vid || 'null'); } catch (e) {}
const recusa = (codigo, erro) => [{ json: { pode: false, codigo, resposta: JSON.stringify({ ok: false, erro }) } }];
if (!deck || !b.chave || b.chave !== deck.chave) return recusa(403, 'Chave errada ou apresentação não encontrada.');
if (!arq || !arq.slides || arq.slides.length !== deck.slides.length || arq.versao !== deck.versao) return recusa(409, 'Os arquivos desta versão ainda não ficaram prontos. Espere o PDF e tente de novo.');
if (vid && ['narrando', 'montando'].includes(vid.estado) && Date.now() - (vid.quando || 0) < 15 * 60000) return recusa(409, 'O vídeo já está sendo feito.');
const fala = s => String(s.narracao || [s.titulo, s.subtitulo, s.texto, (s.itens || []).map(i => i.t).join('. ')].filter(Boolean).join('. ')).replace(/\p{Extended_Pictographic}/gu, '').trim().slice(0, 900);
const segmentos = deck.slides.map(s => ({ n: s.n, texto: fala(s) })).filter(s => s.texto);
const job = `${deck.id}-v${deck.versao}-${Date.now().toString(36)}`.slice(0, 64);
const trilha = deck.op && deck.op.trilha && deck.op.trilha !== 'nenhuma' ? deck.op.trilha : null;
return [{ json: {
  pode: true, codigo: 200, resposta: JSON.stringify({ ok: true, job, slides: segmentos.length }), id: deck.id, versao: deck.versao, job,
  slides: deck.slides.map(s => s.n), cor: deck.t.cor, opcoes: { legendas: !(deck.op && deck.op.legendas === false), trilha, cor: deck.t.cor },
