// Pedido de montagem: a imagem de cada slide + o tempo de cada palavra da narração (para a legenda acender junto).
// A voz devolve as palavras sem pontuação: cada uma é casada com a palavra do texto original ("equipe" ➜ "equipe!"),
// assim a legenda mostra vírgula e ponto e quebra a linha no fim da frase.
const P = $('🧩 Confere e prepara a narração').first().json, N = $('🛠️ Oficina: narra os slides').first().json || {};
const trechos = Array.isArray(N.trechos) ? N.trechos : [];
const textos = {};
try { JSON.parse(P.narrar).segmentos.forEach(s => { textos[s.n] = s.texto; }); } catch (e) {}
const norm = s => String(s || '').toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '').replace(/[^a-z0-9]/g, '');
function alinha(texto, palavras) {
  const toks = String(texto || '').split(/\s+/).filter(Boolean);
  let j = 0;
  return (palavras || []).map(p => {
    const alvo = norm(p.w);
    for (let k = j; alvo && k < Math.min(toks.length, j + 4); k++) {
      if (norm(toks[k]) === alvo) { j = k + 1; return Object.assign({}, p, { w: toks[k] }); }
    }
    return p;   // número falado por extenso etc.: fica a palavra da voz
  });
}
const bons = trechos.filter(t => !t.erro);
const ok = bons.length >= Math.max(2, Math.ceil(P.slides.length * 0.6));
const corpo = { job: P.job, deck: P.id, opcoes: P.opcoes,
  slides: P.slides.map(n => { const t = trechos.find(x => x.n === n) || {}; return { n, palavras: alinha(textos[n], t.palavras) }; }) };
return [{ json: { ok, corpo: JSON.stringify(corpo), narrados: bons.length,
  erro: ok ? '' : 'A narração falhou em ' + (P.slides.length - bons.length) + ' slides: ' + String((trechos.find(t => t.erro) || {}).erro || 'sem resposta').slice(0, 160) } }];

// Andamento do vídeo (a página de andamento e a apresentação mostram a porcentagem).
const P = $('🧩 Confere e prepara a narração').first().json, s = Object.assign({}, $input.item.json || {});
if ($runIndex >= 150 && s.estado !== 'pronto') { s.estado = 'erro'; s.erro = 'O vídeo demorou mais de 15 minutos. Tente de novo.'; }   // laço não fica rodando para sempre
const estado = s.estado === 'pronto' ? 'pronto' : s.estado === 'erro' ? 'erro' : s.estado === 'desconhecido' ? 'erro' : 'montando';
const vid = { estado, progresso: Math.max(5, Math.min(100, Number(s.progresso) || 5)), etapa: String(s.etapa || 'montando o vídeo').slice(0, 120), versao: P.versao, job: P.job,
  quando: Date.now(), video: s.video || '', duracao: s.duracao || 0, tamanho_mb: s.tamanho_mb || 0,
  erro: estado === 'erro' ? String(s.erro || 'a oficina perdeu o trabalho (reiniciou?)').slice(-300) : '' };
return [{ json: { vid: JSON.stringify(vid), terminou: estado !== 'montando', ...vid } }];

// o corpo chega como texto (página) ou JSON (teste)
let b = $('🔔 Pedido do dono (POST)').first().json.body;
if (typeof b === 'string') { try { b = JSON.parse(b); } catch (e) { b = {}; } }
b = b || {};
const base = String($('🔔 Pedido do dono (POST)').first().json.webhookUrl || '').split('/webhook/')[0];
return [{ json: { id: String(b.id || '').replace(/[^a-z0-9-]/g, '').slice(0, 60) || 'nenhum', chave: String(b.chave || ''), acao: String(b.acao || ''),
  campos: b.campos && typeof b.campos === 'object' ? b.campos : {}, base } }];

// Desenho dos slides: o MESMO na página de apresentar, no PDF, nas miniaturas e no vídeo (tela de 1920×1080).
const AP_TEMAS = {
  claro: { nome: 'claro', bg: '#FFFFFF', sup: '#F3F5F8', tinta: '#12151B', tinta2: '#4B5361', linha: '#E2E6EC', ft: 'Montserrat', fc: 'Inter', pesoT: 800, cor: '#2563EB' },
  escuro: { nome: 'escuro', bg: '#0E1117', sup: '#1A1E27', tinta: '#F4F6F9', tinta2: '#A9B2C0', linha: '#2C323D', ft: 'Montserrat', fc: 'Inter', pesoT: 800, cor: '#38BDF8' },
  elegante: { nome: 'elegante', bg: '#FAF7F2', sup: '#F1EADF', tinta: '#1E1A15', tinta2: '#5F574C', linha: '#E3D9C9', ft: 'Playfair Display', fc: 'Inter', pesoT: 700, cor: '#8C5A2B' },
  vibrante: { nome: 'vibrante', bg: '#FFFFFF', sup: '#F6F2FB', tinta: '#16121F', tinta2: '#4E4A57', linha: '#E9E3F1', ft: 'Montserrat', fc: 'Inter', pesoT: 800, cor: '#D6246E' },
  corporativo: { nome: 'corporativo', bg: '#FFFFFF', sup: '#F2F5F9', tinta: '#0B1B33', tinta2: '#46566B', linha: '#DCE3EC', ft: 'Montserrat', fc: 'Inter', pesoT: 700, cor: '#1F5FD1', faixa: '#0B2545' },
};
const AP_LAYOUTS = ['capa', 'secao', 'topicos', 'imagem_texto', 'colunas', 'numeros', 'grafico', 'etapas', 'comparacao', 'citacao', 'fechamento'];
const apHex = h => { h = String(h || '').replace('#', ''); return [0, 2, 4].map(i => parseInt(h.slice(i, i + 2), 16) || 0); };
const apLum = h => apHex(h).map(v => { v /= 255; return v <= 0.03928 ? v / 12.92 : Math.pow((v + 0.055) / 1.055, 2.4); }).reduce((a, v, i) => a + v * [0.2126, 0.7152, 0.0722][i], 0);
const apContraste = (a, b) => { const x = apLum(a), y = apLum(b); return (Math.max(x, y) + 0.05) / (Math.min(x, y) + 0.05); };
const apMistura = (a, b, k) => { const x = apHex(a), y = apHex(b); return '#' + x.map((v, i) => Math.round(v + (y[i] - v) * k).toString(16).padStart(2, '0')).join('').toUpperCase(); };
// cores do tema + a cor de destaque ajustada para aparecer no fundo (>= 3:1, como texto grande e gráfico)
function apTokens(nome, cor) {
  const t = Object.assign({}, AP_TEMAS[nome] || AP_TEMAS.claro);
  let c = /^#[0-9a-fA-F]{6}$/.test(cor || '') ? String(cor).toUpperCase() : t.cor;
