#grade{position:fixed;inset:0 0 64px 0;background:rgba(8,9,12,.97);overflow:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:18px;padding:22px;z-index:5;align-content:start}
#grade button{all:unset;cursor:pointer;display:block;border-radius:10px;outline-offset:3px}
