#lado .nota{flex:1;overflow:auto;font-size:21px;line-height:1.55;background:#15171c;border-radius:12px;padding:16px;color:#e8ebf0;white-space:pre-wrap}
body.apresentador #b-notas,body.apresentador #b-apres{display:none}
dialog{border:0;border-radius:14px;padding:0;background:#000;max-width:min(96vw,1280px);width:100%}
dialog::backdrop{background:rgba(0,0,0,.8)}
dialog video{width:100%;display:block}
dialog form{position:absolute;top:8px;right:8px}dialog form button{background:#0009;color:#fff;border:0;border-radius:10px;padding:8px 12px;font:700 14px Inter,sans-serif;cursor:pointer}
body.cheia #barra{opacity:0}body.cheia.mexeu #barra{opacity:1}body.cheia #progresso{bottom:0}body.cheia #palco{bottom:0}
@media (max-width:760px){#barra .tx,#barra #b-apres,#barra #b-tela{display:none}#barra{gap:2px;padding:0 6px}#barra button,#barra a{padding:0 8px;min-width:40px}#cont{min-width:50px}#notas{font-size:16px}}
@media (max-width:760px) and (orientation:portrait){body.com-notas #palco{bottom:auto;height:calc(56.25vw + 20px)}body.com-notas #progresso{bottom:auto;top:calc(56.25vw + 20px)}
body.com-notas #notas{top:calc(56.25vw + 23px);height:auto}}
@media (prefers-reduced-motion:reduce){#deck .ap-s{transition:none}}
</style></head>
<body class="${modo}${dono ? ' dono' : ''}">
<div id="palco"><div id="deck">${deck.slides.map((s, i) => apSlide(deck, s, i, ARQ)).join('')}</div></div>
<div id="lado" aria-label="Painel do apresentador"><div class="rot">Próximo</div><div class="prox" id="prox-mini"></div>
<div class="tempo"><span id="relogio">00:00</span><small id="hora"></small><button id="zera" type="button">Zerar</button></div><div class="rot">Notas</div><div class="nota" id="nota-ap"></div></div>
<div id="progresso"></div>
<nav id="barra" aria-label="Controles da apresentação">
<button id="ant" type="button" aria-label="Slide anterior">◀</button><span id="cont" aria-live="polite">1 / ${deck.slides.length}</span><button id="prox" type="button" aria-label="Próximo slide">▶</button>
<span class="esp"></span>
<button id="b-grade" type="button" aria-pressed="false" title="Todos os slides (G)">▦ <span class="tx">Todos</span></button>
<button id="b-notas" type="button" aria-pressed="false" title="Notas do apresentador (N)">📝 <span class="tx">Notas</span></button>
<button id="b-apres" type="button" title="Modo apresentador numa outra janela (P)">🎤 <span class="tx">Apresentador</span></button>
<button id="b-tela" type="button" title="Tela cheia (F)">⛶ <span class="tx">Tela cheia</span></button>
<div class="menu"><button id="b-baixar" type="button" aria-expanded="false" aria-controls="m-baixar">⬇️ <span class="tx">Baixar</span></button><div class="lista" id="m-baixar" hidden></div></div>
<button id="b-compart" type="button" title="Compartilhar o link">🔗 <span class="tx">Compartilhar</span></button>
${dono ? '<button id="b-editar" type="button" aria-pressed="false" title="Editar os textos">✏️ <span class="tx">Editar</span></button>' : ''}
</nav>
<aside id="notas" hidden aria-label="Notas do apresentador"><h3>Notas do slide <span id="n-num">1</span></h3><div class="so-ver" id="nota-txt"></div>
<div class="so-ed"><textarea id="nota-ed" aria-label="Notas do apresentador"></textarea><h3 style="margin-top:12px">Fala do vídeo narrado</h3><textarea id="narr-ed" aria-label="Fala do vídeo narrado"></textarea></div></aside>
<div id="grade" hidden role="dialog" aria-label="Todos os slides"></div>
<div id="preto" hidden title="Clique para voltar"></div>
<div id="edbar" role="toolbar" aria-label="Edição"><span>✏️ Clique num texto do slide para mudar · notas no painel 📝</span><button id="salvar" type="button" disabled>💾 Salvar</button><button id="sair-ed" type="button">Sair</button></div>
<div id="aviso" role="status"></div>
<dialog id="dlg-video"><form method="dialog"><button>Fechar ✕</button></form><video id="v-el" controls preload="none" playsinline></video></dialog>
<script>
var D = ${JSON.stringify(cli).replace(/</g, '\\u003c')};
${AP_AJUSTA}
(function () {
  var el = function (s) { return document.querySelector(s); }, palco = el('#palco'), deck = el('#deck'), secs = [].slice.call(deck.querySelectorAll('.ap-s'));
  var N = secs.length, i = 0, editando = false, sujo = false, mudouNota = {}, mudouNarr = {};
  var canal = 'BroadcastChannel' in window ? new BroadcastChannel('ap-' + D.id) : null;
  function aviso(t, ms) { var a = el('#aviso'); a.textContent = t; a.classList.add('on'); clearTimeout(aviso.t); aviso.t = setTimeout(function () { a.classList.remove('on'); }, ms || 2600); }
  function escala(box, alvo) { var r = box.getBoundingClientRect(), s = Math.min(r.width / 1920, r.height / 1080); alvo.style.transform = 'translate(' + ((r.width - 1920 * s) / 2) + 'px,' + ((r.height - 1080 * s) / 2) + 'px) scale(' + s + ')'; }
  function encaixa() { escala(palco, deck); var pm = el('#prox-mini'); if (pm.firstChild) escalaMini(pm); }
  function escalaMini(box) { var s = box.getBoundingClientRect().width / 1920; if (box.firstChild) box.firstChild.style.transform = 'scale(' + s + ')'; }
  function mini(k) { var c = secs[k].cloneNode(true); c.classList.add('atual'); c.querySelectorAll('[data-c]').forEach(function (x) { x.removeAttribute('data-c'); x.removeAttribute('contenteditable'); }); c.removeAttribute('aria-label'); c.setAttribute('aria-hidden', 'true'); return c; }
  function mostraNota() {
    el('#n-num').textContent = i + 1;
    el('#nota-txt').textContent = D.notas[i] || 'Sem notas neste slide.';
    el('#nota-ap').textContent = D.notas[i] || 'Sem notas neste slide.';
    el('#nota-ed').value = D.notas[i] || ''; el('#narr-ed').value = D.narr[i] || '';
    var pm = el('#prox-mini'); pm.innerHTML = '';
    if (D.modo === 'apresentador') { if (i + 1 < N) { pm.appendChild(mini(i + 1)); escalaMini(pm); } else pm.innerHTML = '<div style="display:grid;place-items:center;height:100%;color:#98a1ae;font:600 16px Inter">Fim da apresentação</div>'; }
  }
  function vai(k, deFora) {
    k = Math.max(0, Math.min(N - 1, k));
    secs[i].classList.remove('atual'); i = k; secs[i].classList.add('atual');
    el('#cont').textContent = (i + 1) + ' / ' + N; el('#progresso').style.width = ((i + 1) / N * 100) + '%';
    try { history.replaceState(null, '', location.pathname + location.search + '#' + (i + 1)); } catch (e) {}
    mostraNota();
    if (!deFora && canal) canal.postMessage({ i: i });
  }
  if (canal) canal.onmessage = function (e) { if (e.data && typeof e.data.i === 'number' && e.data.i !== i) vai(e.data.i, true); };
  function notas(on) { var a = el('#notas'), v = typeof on === 'boolean' ? on : a.hidden; a.hidden = !v; document.body.classList.toggle('com-notas', v); el('#b-notas').setAttribute('aria-pressed', v); setTimeout(encaixa, 20); }
  function grade(on) {
    var g = el('#grade'), v = typeof on === 'boolean' ? on : g.hidden;
    if (v) {
      g.innerHTML = '';
      secs.forEach(function (s, k) {
        var b = document.createElement('button'); b.type = 'button'; b.className = k === i ? 'ativo' : ''; b.setAttribute('aria-label', 'Ir para o slide ' + (k + 1));
        var m = document.createElement('div'); m.className = 'mi'; m.appendChild(mini(k)); b.appendChild(m);
        var t = document.createElement('span'); t.textContent = (k + 1) + '. ' + ((s.querySelector('h1,h2,blockquote') || {}).textContent || '').slice(0, 60); b.appendChild(t);
        b.onclick = function () { vai(k); grade(false); };
        g.appendChild(b);
      });
      g.hidden = false;
      g.querySelectorAll('.mi').forEach(function (m) { escalaMini(m); });
      var at = g.querySelector('.ativo'); if (at) at.focus();
    } else g.hidden = true;
    el('#b-grade').setAttribute('aria-pressed', v);
  }
  function tela() { if (document.fullscreenElement) document.exitFullscreen(); else if (document.documentElement.requestFullscreen) document.documentElement.requestFullscreen().catch(function () { aviso('Seu navegador não deixou abrir em tela cheia.'); }); else aviso('Tela cheia não funciona neste navegador.'); }
  document.addEventListener('fullscreenchange', function () { document.body.classList.toggle('cheia', !!document.fullscreenElement); setTimeout(encaixa, 60); });
  var parado; document.addEventListener('mousemove', function () { document.body.classList.add('mexeu'); clearTimeout(parado); parado = setTimeout(function () { document.body.classList.remove('mexeu'); }, 2200); });
  function preto() { el('#preto').hidden = !el('#preto').hidden; }
  el('#preto').onclick = preto;
  function apresentador() { var w = window.open(location.pathname + '?modo=apresentador' + (D.chave ? '&chave=' + D.chave : '') + '#' + (i + 1), 'ap-' + D.id, 'width=1280,height=800'); if (!w) aviso('Libere as janelas (pop-up) para abrir o modo apresentador.'); else aviso('Modo apresentador aberto: as duas janelas andam juntas.'); }
  el('#ant').onclick = function () { vai(i - 1); }; el('#prox').onclick = function () { vai(i + 1); };
  el('#b-grade').onclick = function () { grade(); }; el('#b-notas').onclick = function () { notas(); }; el('#b-apres').onclick = apresentador; el('#b-tela').onclick = tela;
  // baixar
  var mb = el('#m-baixar');
  function montaBaixar() {
    var h = '';
    if (D.pdf) h += '<a href="' + D.pdf + '" target="_blank" rel="noopener" download>📄 PDF <small>' + (D.atual ? 'para imprimir' : 'versão anterior') + '</small></a>';
    if (D.pptx) h += '<a href="' + D.pptx + '" target="_blank" rel="noopener" download>📊 PowerPoint (PPTX) <small>editável</small></a>';
    if (D.video) h += '<button type="button" id="ver-video">🎬 Vídeo narrado <small>' + (D.video_versao === D.versao ? 'assistir' : 'versão anterior') + '</small></button><a href="' + D.video + '" download>⬇️ Baixar o vídeo (MP4)</a>';
    else if (D.video_estado === 'narrando' || D.video_estado === 'montando') h += '<button type="button" disabled>🎬 Vídeo <small>sendo feito…</small></button>';
    if (D.dono) h += '<button type="button" id="fazer-video">🎬 ' + (D.video ? 'Refazer o vídeo narrado' : 'Fazer o vídeo narrado') + '</button>';
    mb.innerHTML = h || '<button type="button" disabled>Os arquivos ainda estão sendo feitos…</button>';
    var vv = el('#ver-video'); if (vv) vv.onclick = function () { el('#v-el').src = D.video; el('#dlg-video').showModal(); el('#v-el').play().catch(function () {}); };
    var fv = el('#fazer-video'); if (fv) fv.onclick = fazerVideo;
  }
  montaBaixar();
  el('#b-baixar').onclick = function (e) { e.stopPropagation(); mb.hidden = !mb.hidden; el('#b-baixar').setAttribute('aria-expanded', !mb.hidden); };
  document.addEventListener('click', function (e) { if (!mb.hidden && !e.target.closest('.menu')) { mb.hidden = true; el('#b-baixar').setAttribute('aria-expanded', 'false'); } });
  el('#dlg-video').addEventListener('close', function () { el('#v-el').pause(); });
  el('#b-compart').onclick = function () {
    if (navigator.share) navigator.share({ title: D.titulo, url: D.link }).catch(function () {});
    else if (navigator.clipboard) navigator.clipboard.writeText(D.link).then(function () { aviso('Link copiado: é só colar no WhatsApp ou no e-mail.'); });
    else prompt('Copie o link:', D.link);
  };
  // teclado, toque e clique
  document.addEventListener('keydown', function (e) {
    var t = e.target; if (t.isContentEditable || /INPUT|TEXTAREA|SELECT/.test(t.tagName)) { if (e.key === 'Escape') t.blur(); return; }
    if (el('#dlg-video').open) return;
    var k = e.key;
    if ((k === ' ' || k === 'Enter') && /^(BUTTON|A)$/.test(t.tagName)) return;   // o botão focado já age sozinho
    if (['ArrowRight', 'PageDown', ' ', 'Enter'].indexOf(k) > -1) { e.preventDefault(); vai(i + 1); }
    else if (['ArrowLeft', 'PageUp', 'Backspace'].indexOf(k) > -1) { e.preventDefault(); vai(i - 1); }
    else if (k === 'Home') vai(0); else if (k === 'End') vai(N - 1);
    else if (k === 'f' || k === 'F') tela(); else if (k === 'n' || k === 'N') notas(); else if (k === 'g' || k === 'G') grade();
    else if (k === 'b' || k === 'B' || k === '.') preto(); else if (k === 'p' || k === 'P') apresentador();
    else if (k === 'Escape') { grade(false); if (!el('#preto').hidden) preto(); }
  });
  var x0 = null, y0 = null;
  palco.addEventListener('touchstart', function (e) { x0 = e.touches[0].clientX; y0 = e.touches[0].clientY; }, { passive: true });
  palco.addEventListener('touchend', function (e) { if (x0 === null || editando) return; var dx = e.changedTouches[0].clientX - x0, dy = e.changedTouches[0].clientY - y0; if (Math.abs(dx) > 45 && Math.abs(dx) > Math.abs(dy)) { vai(i + (dx < 0 ? 1 : -1)); palco.dataset.toque = Date.now(); } x0 = null; });
  palco.addEventListener('click', function (e) {
    if (editando || Date.now() - (palco.dataset.toque || 0) < 400) return;
    var r = palco.getBoundingClientRect(), x = e.clientX - r.left; if (x > r.width * 0.55) vai(i + 1); else if (x < r.width * 0.45) vai(i - 1);
  });
  window.addEventListener('resize', encaixa);
  // modo apresentador: relógio da fala e hora
  if (D.modo === 'apresentador') {
    var t0 = Date.now(); el('#zera').onclick = function () { t0 = Date.now(); };
    setInterval(function () { var s = Math.floor((Date.now() - t0) / 1000); el('#relogio').textContent = String(Math.floor(s / 60)).padStart(2, '0') + ':' + String(s % 60).padStart(2, '0');
      el('#hora').textContent = new Date().toLocaleTimeString('pt-BR', { hour: '2-digit', minute: '2-digit' }); }, 500);
  }
  // edição (só com a chave)
  function editar(on) {
    editando = on; document.body.classList.toggle('editando', on); var be = el('#b-editar'); if (be) be.setAttribute('aria-pressed', on);
    deck.querySelectorAll('[data-c]').forEach(function (x) {
      if (on) { if (x.dataset.orig === undefined) x.dataset.orig = x.textContent; x.setAttribute('contenteditable', 'plaintext-only'); if (x.contentEditable !== 'plaintext-only') x.setAttribute('contenteditable', 'true'); x.setAttribute('spellcheck', 'true'); }
      else x.removeAttribute('contenteditable');
    });
    if (on) { notas(true); aviso('Modo edição: clique num texto do slide. Enter não pula linha.', 3500); } else setTimeout(encaixa, 20);
  }
  function marca() { sujo = true; el('#salvar').disabled = false; }
  deck.addEventListener('input', function (e) { marca(); apAjusta(e.target.closest('.ap-s')); });
  deck.addEventListener('keydown', function (e) { if (editando && e.key === 'Enter') { e.preventDefault(); e.target.blur(); } });
  deck.addEventListener('paste', function (e) { if (!editando) return; e.preventDefault(); var t = (e.clipboardData || window.clipboardData).getData('text/plain').replace(/\\s+/g, ' '); document.execCommand('insertText', false, t); });
  el('#nota-ed').addEventListener('input', function () { D.notas[i] = this.value; mudouNota[i] = 1; marca(); });
  el('#narr-ed').addEventListener('input', function () { D.narr[i] = this.value; mudouNarr[i] = 1; marca(); });
  if (D.dono) {
    el('#b-editar').onclick = function () { editar(!editando); };
    el('#sair-ed').onclick = function () { if (sujo && !confirm('Sair sem salvar as mudanças?')) return; if (sujo) location.reload(); else editar(false); };
    el('#salvar').onclick = function () {
      var campos = {}, n = 0;
      deck.querySelectorAll('[data-c]').forEach(function (x) { if (x.textContent !== x.dataset.orig && x.dataset.orig !== undefined) { campos[x.dataset.c] = x.textContent; n++; } });
      Object.keys(mudouNota).forEach(function (k) { campos[k + '.notas'] = D.notas[k]; n++; });
      Object.keys(mudouNarr).forEach(function (k) { campos[k + '.narracao'] = D.narr[k]; n++; });
      if (!n) { aviso('Nada mudou.'); return; }
